export const usageExtra = {
  "about": {"c":["talk about","about to leave","what about you","about ten people","think about it"],"b":"about 源自古英语 abūtan，由 a-（on）+ būtan（outside）构成，本义是「在……周围」，后引申出「关于」和「大约」。中国学习者容易把 be about to 误解为「关于」，其实它表示「即将做某事」，且不能与具体时间状语连用。另外 about 表「大约」时比 approximately 更口语化。"},
  "accumulate": {"u":"强调逐渐积累，及物不及物均可。"},
  "accuracy": {"u":"指与真值的接近度；与 precision 精密度不同。"},
  "accurate": {"u":"指符合事实、误差小；名词 accuracy。"},
  "adaptable": {"u":"勿与 adopt 混；指适应力强或可改编。"},
  "addict": {"c":["a drug addict","be addicted to","a computer addict","addict sb to sth","recover from addiction"],"b":"addict 源自拉丁语 addictus，是 addicere（判给、使归属于）的过去分词，古罗马法庭把欠债人判给债主，后来引申为「沉溺于某事物的人」。名词 addict 重音在前，动词 addict 重音在后；常用被动 be addicted to。中国学习者常漏掉 to 后接动名词的规则：be addicted to playing games。","u":"be addicted to 后接名词或动名词，如 addicted to ga"},
  "aggregation": {"u":"指聚集或汇总；数据领域常用 data aggregation。"},
  "alexander the great": {"u":"古马其顿国王，东征建立横跨欧亚非帝国。"},
  "all": {"c":["all of us","all the time","all in all","after all","all over the world"],"b":"all 源自古英语 eall，兼作形容词、代词和副词。中国学习者常犯的错是 all 与 both 混用：all 用于三者及以上，both 只用于两者。另外 all 作主语时，谓语单复数取决于所指：All is well 指整体，All are here 指个体。"},
  "am": {"c":["I am a student","I am from China","I am sorry","I am afraid","here I am"],"b":"am 源自古英语 eom，是 be 动词的第一人称单数现在式，只与 I 搭配，这是英语保留下来的一种不规则变化。中国学习者最容易漏掉它，说成 I a student 或 I student，因为汉语「我是学生」的「是」有时可省。记住：英语每个句子必须有动词，I 后面永远跟 am，不能跟 is 或 are。"},
  "ambiguity": {"u":"指可作多种解释；合同法律中多含贬义。"},
  "ambiguous": {"u":"指可作多种解释的、含糊的；勿混 ambivalent。"},
  "an": {"c":["an apple","an hour","an honest man","an old friend","an English book"],"b":"an 源自古英语 an，即数词「一」，后分化出 a 与 an。规则并非看字母而是看读音：以元音音素开头用 an，如 an hour 中 h 不发音，故用 an；a university 中虽以元音字母开头，但读辅音，故用 a。"},
  "analogy": {"u":"draw an analogy between A and B；by"},
  "analytical": {"u":"指分析的、善于分析的；analytical skills 为高频搭配。"},
  "and": {"c":["black and white","you and I","come and see","and so on","nice and warm"],"b":"and 是英语最古老、使用频率最高的连词之一。它除了连接并列成分，还能表示“然后”“结果”甚至“对比”。中国学习者常犯的错是在否定句中用 and 代替 or，如 I don't like tea and coffee 会被理解为“两样都不喜欢”，其实想说“不喜欢茶和咖啡”应说 tea or coffee。"},
  "annihilation": {"u":"语气极强，指彻底毁灭；物理中指湮灭。"},
  "anniversary": {"c":["celebrate an anniversary","the tenth anniversary","wedding anniversary","mark the anniversary","on the anniversary of"],"b":"源自拉丁语 anniversarius，annus（年）+ vertere（转），意为「每年转回来的日子」。它最初用于宗教纪念日，后泛指一切周年。注意它指「满一年的纪念」，不是「生日」；中文说「一周年纪念日」对应 the first anniversary，而「百天纪念」不能用 anniversary。","u":"指周年纪念日；十周年说 tenth anniversary。"},
  "annual": {"c":["annual meeting","annual report","annual income","annual event","on an annual basis"],"b":"annual 源自拉丁语 annus（年），词根 ann- 出现在 anniversary（周年）、annuity（年金）等词中。它既指「每年发生的」，也指「按年计算的」。学习者易与 anniversary 混淆：annual 是形容词「年度的」，而 anniversary 是名词「周年纪念日」。","u":"形容词，表「每年的」；按年计算常用 on an annual basis。"},
  "anthropology": {"u":"指人类学；学科名通常不加冠词。"},
  "antibiotic": {"u":"指抗生素；antibiotic resistance 抗生素耐药性。"},
  "any": {"c":["any of these books","at any time","in any case","any other questions","without any doubt"],"b":"any 源自古英语 ænig，本义就是「一个的」，与 one 同源。现代英语中它主要用于疑问句、否定句和条件句，这是中国学习者最容易出错的地方：肯定句里通常用 some 而非 any。不过在 if 从句和表示「任何一个都」的强调语境中，any 也可用于肯定句，如 Any student can join。"},
  "apathy": {"u":"指对事物冷漠麻木，常与 voter apathy 搭配。"},
  "apology": {"c":["make an apology","accept an apology","offer a sincere apology","owe sb an apology","a public apology"],"b":"apology 源自希腊语 apologia，本义“辩护、辩解”，所以它既可指道歉，也可指辩解（如 apologize for 为…辩解）。中国学习者最常犯的错是把动词 apologize 当名词用，说 I give you apologize；正确搭配是 make an apology to sb。","u":"动词是 apologize；名词搭配 make an apology to sb"},
  "applaud": {"u":"称赞某人时直接接宾语：applaud his courage。"},
  "appreciation": {"u":"兼指欣赏、感激与增值；经济义与 depreciation 相对。"},
  "are": {"c":["are you serious","are about to start","are not allowed here","there are many reasons","are you with me"],"b":"are 是 be 的现在时复数及第二人称单数形式，源自古英语 earun。它常与 there 构成 there are 存在句，表示「有」。中国学习者易犯的错是把 are 与 is 混用，记住：you 无论单复数都用 are，这是英语中少数保留的尊称一致现象。"},
  "armed": {"u":"armed with 可引申为「具备…」：armed with facts。"},
  "arrangement": {"c":["make arrangements for","travel arrangements","a seating arrangement","come to an arrangement","by prior arrangement"],"b":"arrangement 由动词 arrange（安排、排列）加名词后缀 -ment 构成，arrange 源自法语 arranger，本义为「排成一行」。它既可指抽象的「安排、约定」，也可指具体的「排列、布置」。学习者常忘记其可数性，表示「做安排」时多用复数 make arrangements。","u":"表「做安排」时常用复数：make arrangements for sth。"},
  "artificial": {"u":"指人造仿制品，常含「不自然」意味：artificial smile。"},
  "artless": {"u":"指天真不做作；反义为 artful（狡黠的）。"},
  "as": {"c":["as soon as","as well as","as if","as long as","as usual"],"b":"as 源自古英语 ealswā，本义是「完全如此」，后简化为 as，用法极其丰富，可作连词、介词和副词。中国学习者最易混淆 as 与 like：as 作连词接句子，like 作介词接名词。另外 as well as 连接主语时，谓语动词与前者一致，如 Tom as well as I is here，这是常见语法点。"},
  "ascribe": {"u":"用 ascribe A to B，把 A 归因于 B。"},
  "aspect": {"u":"指方面、层面，常用 every aspect of life。"},
  "assertion": {"u":"常含未经证实之意，搭配 make an assertion。"},
  "assist": {"u":"较正式；assist sb with sth 或 in doing。"},
  "assume": {"u":"假定、承担、呈现三义；假定常含未证实。"},
  "at": {"c":["at home","at night","good at","at the moment","at least"],"b":"at 源自古英语 æt，本义是「在……点」，与拉丁语 ad 同源。它主要用于表示具体的时间点、地点或状态，与 in（大范围）、on（表面）形成对比。中国学习者最易混的是时间表达：at 用于钟点和瞬间，in 用于年月季节，on 用于具体某天。此外 be good at 后接动名词，不能接原形。"},
  "athlete": {"u":"泛指运动员，尤指田径选手；athlete's foot 指脚气。"},
  "attempt": {"u":"attempt to do 最常用，后接不定式，不接动名词。"},
  "attention": {"u":"pay attention to 中 to 为介词，后接名词或动名词。"},
  "attribute": {"u":"动词用 attribute A to B；名词重音在前。"},
  "authorize": {"u":"常用 be authorized to do，表示「获授权做某事」。"},
  "autograph": {"u":"指名人亲笔签名；普通签名多用 signature。"},
  "avenue": {"u":"本指大道，引申为途径，如 explore every avenue。"},
  "awesome": {"u":"本义令人敬畏，口语中弱化为极好的。"},
  "bakery": {"u":"指面包房；-ery 表场所，勿与 baker 混。"},
  "basic": {"u":"指起码、入门层面的；basic salary 指基本工资。"},
  "be": {"c":["be careful with","be about to","be worth doing","be used to doing","be responsible for"],"b":"be 是英语中最不规则也最核心的动词，源自古英语 bēon，兼有「存在」和「系词」两义。它最大的特点是形态多变（am/is/are/was/were/been/being），中国学习者易漏掉它，说 I tired 而非 I am tired，需牢记汉语形容词作谓语时英语要加 be。"},
  "because": {"c":["because of","because I was tired","just because","mainly because","not because...but because"],"b":"because 由 by 与 cause（原因）合成，字面就是「由于这个原因」，是英语中最直接的因果连词。中国学习者最大的陷阱是 because 与 so 不能同时用，中文「因为……所以……」直译成 because...so... 是典型错误，英语二选一即可。另外 because of 是介词短语，后面只能接名词或动名词，不能接句子。"},
  "been": {"c":["have been to","has been doing","been there done that","have been in","never been better"],"b":"been 是 be 的过去分词。have been to 表示“去过某地（已回来）”，而 have gone to 表示“去了未回”，这是中国学习者最易混的一对。been there, done that 是口语习语，意为“经历过了，不新鲜”。"},
  "big": {"c":["a big deal","big difference","big city life","make it big","big on details"],"b":"big 源自古诺斯语 bugge，最初带有「重要、强大」的意味，因此英语中 big 常不指体积而指重要性，如 a big decision、big news。中国学习者容易只用它表示「尺寸大」，忽略「重大、有名」这一引申义，如 make it big 意为「一举成名」。","u":"除「尺寸大」外，更常表「重要的」，如 a big decision、big ne"},
  "biography": {"u":"指他人写的传记；自传是 autobiography。"},
  "biology": {"c":["study biology","marine biology","molecular biology","a degree in biology","biology teacher"],"b":"由希腊语 bios（生命）+ logos（学问、研究）构成，字面就是「研究生命的学问」。19 世纪初由法国学者拉马克等人正式确立为学科名。中国学习者易把 biology 与 biography（传记）混淆，后者词根是 bio+graphy（写），意为「写生平」，两者虽同含 bio-，含义完全不同。","u":"学科名，通常不加冠词，如 study biology。"},
  "blemishless": {"c":["a blemishless record","a blemishless complexion","remain blemishless","a blemishless reputation","perfectly blemishless"],"b":"由 blemish（瑕疵、污点）+ 否定后缀 -less 构成，字面即「没有瑕疵的」。blemish 源自古法语 blemir（使变苍白、损伤），原指皮肤上的斑点，后引申为名誉上的污点。这个词属于书面雅语，日常口语更常说 flawless 或 spotless；中国学习者使用时要注意它偏正式，适合描写肌肤、记录、声誉。","u":"书面雅语，日常口语更常用 flawless 或 spotless。"},
  "boards": {"u":"复数可指董事会；on the boards 指登台。"},
  "brancusi": {"u":"罗马尼亚雕塑家，以极简抽象造型著称。"},
  "bulletproof": {"u":"bulletproof vest 指防弹背心，为最高频搭配。"},
  "but": {"c":["but not least","nothing but trouble","all but finished","but for your help","last but not least"],"b":"but 源自古英语 būtan（在外面、除外），所以它兼有「但是」和「除了」两义，如 everyone but Tom。中国学习者常把 but 与 however 混用：but 是并列连词，连接两个分句时前面一般用逗号，而 however 是副词，需用分号或句号隔开。"},
  "by": {"c":["by the way","by myself","by bus","by the time","by chance"],"b":"by 源自古英语 bī，本义是“靠近”，后引申出“通过、被、在……之前”等义。中国学习者常混淆 by 与 with 表示交通工具：by 后接不加冠词的交通工具，如 by bus；若加冠词则用 on，如 on the bus。"},
  "calder": {"u":"美国雕塑家，以活动雕塑 mobile 著称。"},
  "can": {"c":["can you help me","can hardly wait","can do better","can't stand it","as fast as you can"],"b":"can 源自古英语 cunnan（知道、有能力），所以它本义偏「懂得如何做」，后引申为「能够」。它没有不定式，也不能加 to，中国学习者常错说 to can 或 can to do。否定 can't 在美式英语中常读作 cannot 的缩合，注意与 may 的许可义区分。"},
  "capital": {"u":"capital city 指首都；raise capital 指筹集资本。"},
  "capitalism": {"u":"由 capital + -ism 构成，指资本主义制度。"},
  "careless": {"c":["careless mistakes","careless about details","a careless driver","careless with money","careless remark"],"b":"careless 由 care（小心）+ -less（无）构成，字面就是「没有小心的」。它既可指做事粗心（careless mistakes 粗心造成的错误），也可指对某事不在乎（careless about one's appearance）。中国学习者常把 careless 与 carefree（无忧无虑）混用，后者是褒义，前者多含批评。","u":"「粗心犯的错」说 careless mistakes，是常见搭配。"},
  "cassatt": {"u":"美国印象派女画家，以母子题材闻名。"},
  "catalogue": {"c":["a product catalogue","catalogue the collection","an online catalogue","catalogue the books","a library catalogue"],"b":"catalogue 源自希腊语 katalogos，kata-（向下）+ legein（列举），本义是「逐一列出」。英式拼写 catalogue，美式常缩为 catalog。它既可作名词（商品目录、图书目录），也可作动词（编目、分类登记）。中国学习者常只记名词义，忽略动词用法 catalogue the items。","u":"英式拼写 catalogue，美式常作 catalog；可作动词「编目」。"},
  "cellini": {"u":"意大利文艺复兴雕塑家，以《珀尔修斯》著称。"},
  "charlemagne": {"u":"法兰克国王，800年加冕为罗马人皇帝。"},
  "christopher columbus": {"u":"意大利航海家，1492年抵达美洲。"},
  "chronic": {"c":["chronic disease","chronic pain","a chronic shortage","chronic unemployment","chronic illness"],"b":"chronic 源自希腊语 chronos（时间），本义是「与时间有关的」，所以指长期存在、难以根治的，如 chronic disease（慢性病）。它与 acute（急性的）相对。中国学习者常把 chronic 误解为「严重」，其实核心是「长期、反复」，如 chronic shortage 指长期短缺而非严重短缺。","u":"chronic 指「长期的、慢性的」，与 acute（急性的）相对。"},
  "chronicle": {"u":"名词指编年史；动词指按时间顺序记录。"},
  "chronology": {"u":"常与 order 连用：in chronological order"},
  "cite": {"u":"学术写作中 cite a source 指引用来源，须注明出处。"},
  "civilization": {"u":"指文明或某一文明，如 ancient civilization 古文明。"},
  "clarification": {"u":"ask for clarification 指请求澄清，比再问一次更正式。"},
  "closure": {"u":"强调最终关闭；sense of closure 指了结感。"},
  "colonial": {"u":"指殖民统治或殖民地相关的，如 colonial rule。"},
  "combat": {"u":"作动词常接 crime、inflation 等抽象名词。"},
  "command": {"u":"command respect 表赢得尊重；也指掌握。"},
  "commercial": {"u":"作名词指电视广告；commercial bank 指商业银行。"},
  "commercially": {"u":"常搭 viable、available，指商业上可行或有售。"},
  "commitment": {"c":["make a commitment","a strong commitment to","fulfil a commitment","a long-term commitment","lack of commitment"],"b":"由动词 commit（托付、使承担）加名词后缀 -ment 构成，本义是「把事情托付出去」，引申为「承诺、投入、献身」。常见搭配是 commitment to sth。中文学习者易与 promise 混用：promise 偏口头许诺，commitment 强调持续的责任与投入。","u":"常搭 commitment to sth，强调持续的责任与投入。"},
  "compassion": {"u":"指同情并愿相助；常用 compassion for sb。"},
  "compose": {"c":["compose a poem","be composed of","compose oneself","compose an email","compose music"],"b":"compose 源自拉丁语 componere，由 com-（一起）与 ponere（放置）构成，本义「放在一起」，故有「组成」与「创作」两义。be composed of 意为「由……组成」，与 consist of 同义但用被动形式。学习者易误写为 be composed by，其实 by 用于被动施动者，此处应选 of。","u":"be composed of 意为「由……组成」，介词用 of，不用 by。"},
  "concern": {"u":"be concerned about 担忧；with 表有关。"},
  "concerned": {"u":"be concerned about 表担忧；the people"},
  "conduct": {"c":["conduct an experiment","conduct a survey","conduct oneself well","conduct electricity","under his conduct"],"b":"conduct 源自拉丁语 conducere，由 con-（一起）加 ducere（引导）构成，本义是「带领、引导」。作动词时重音在后，作名词「行为」时重音在前，这种「重音区分词性」的现象在英语中很典型。作名词时它多指人的品行，而实验、调查等「实施」义则用动词，学习者常把两者混用。","u":"作动词重音在后，作名词「行为」重音在前；conduct an experimen"},
  "confident": {"u":"be confident of/about 表对…有信心，后接名词或动名词。"},
  "confirmation": {"u":"常指预订或信息的确认，如 confirmation email。"},
  "conflict": {"u":"名词重音在前，动词在后；conflict with 表冲突。"},
  "confucius": {"u":"指人时通常不加 the，直接作主语或宾语。"},
  "conscious": {"u":"be conscious of 表意识到；勿与 conscience 混。"},
  "consensus": {"u":"指共识；常用 reach a consensus on sth。"},
  "consequence": {"c":["as a consequence of","face the consequences","serious consequences for","of little consequence","in consequence of"],"b":"consequence 由拉丁语 consequi（跟随）派生，con-（一起）加 sequi（跟随），字面意思是「随之而来的东西」，所以它强调因果链条中的「结果」。中国学习者常把它与 result 混用，其实 consequence 多带负面或严重的意味，如 face the consequences（承担后果），而 result 更中性。","u":"多指不好的「后果」，常用 face the consequences；与 res"},
  "consolation": {"u":"指失意时的安慰；consolation prize 为安慰奖。"},
  "conspicuous": {"u":"指显眼、引人注目的；conspicuous consumption。"},
  "construct": {"c":["construct a building","construct an argument","construct a theory","construct a bridge","socially constructed"],"b":"源自拉丁语 construere，con-（共同）加 struere（堆砌、建造），本义是「堆叠建造」。除「建造实物」外，还常指「构思、构建」抽象事物，如 construct a theory/argument。中文学习者易只记「建造」，忽略其学术语境中的「建构」义。","u":"除建造实物外，还指构建理论、论点等抽象事物。"},
  "construction": {"u":"under construction 表施工中；也指建造过程。"},
  "contemporary": {"c":["contemporary art","contemporary society","a contemporary of Shakespeare","contemporary culture","contemporary issues"],"b":"由 con-（共同）加 tempor（时间）构成，字面意思是「同一时间的」。作形容词指「当代的」，作名词指「同时代的人」，如 a contemporary of Mozart。中文学习者易把它与 modern 混用：contemporary 侧重「当今、同处一个时代」，modern 侧重「现代的、新式的」。","u":"作名词指同时代的人，如 a contemporary of his。"},
  "contend": {"u":"contend for 争夺；contend with 应付；contend"},
  "continuity": {"u":"指连续性；ensure continuity 表保证延续不断。"},
  "contradict": {"c":["contradict oneself","contradict a statement","contradict the evidence","contradict each other","flatly contradict"],"b":"contradict 来自拉丁语 contra-（相反）+ dicere（说），字面就是「说相反的话」，与 predict（预言）、dictate（口述）同根。它既可指反驳他人，也可指两事物互相矛盾。中国学习者常犯的错是 contradict oneself（自相矛盾）中漏掉反身代词，说成 contradict self。","u":"「自相矛盾」说 contradict oneself，必须用反身代词。"},
  "contradiction": {"u":"a contradiction in terms 指自相矛盾的说法。"},
  "contribute": {"u":"contribute to 表贡献于；投稿用 contribute sth"},
  "convention": {"c":["break with convention","social conventions","attend a convention","the Geneva Convention","by convention"],"b":"源自拉丁语 convenire（聚集、一致），所以一词多义都围绕「共同」：大家共同遵守的就是「惯例」，共同聚在一起就是「大会」，共同商定的就是「公约」。中文学习者常只记住「会议」义，忽略「社会惯例」这一更常见的抽象用法。","u":"指社会惯例时常用复数 conventions，如 social conventi"},
  "corporate": {"u":"指公司的、法人的，常搭 culture、image。"},
  "could": {"c":["could you","could be","could have done","couldn't help","as ... as could be"],"b":"could 是 can 的过去式，但也可表示委婉请求或可能性。中国学习者常混淆 could 与 can：could 更委婉，如 Could you help me? 比 Can you help me? 礼貌。could have done 表示“本可以做却没做”，含遗憾语气。"},
  "credentials": {"u":"常用复数，present/check credentials；指学历资历时也说"},
  "credible": {"c":["a credible witness","credible evidence","hardly credible","credible threat","credible source"],"b":"源自拉丁语 credibilis，词根 cred- 意为「相信」，与 credit、creed 同源。常见误用是与 credulous（轻信的）混淆：credible 指「某事可信」，credulous 指「人易轻信」。另外 credible 与 creditable（值得称赞的）也常被搞混，记住 credible 只跟「信不信」有关。","u":"修饰事物「可信」，不用于人；人易轻信用 credulous。"},
  "creed": {"u":"多指成体系、公开宣示的信条，比 belief 庄重。"},
  "curiosity": {"c":["out of curiosity","arouse curiosity","satisfy one's curiosity","intellectual curiosity","a sense of curiosity"],"b":"curiosity 来自拉丁语 cura（关心、留意），与 curious（好奇的）、care（关心）同根，本义是「想要了解」。英语谚语 Curiosity killed the cat 提醒人别多管闲事。中国学习者常把 out of curiosity（出于好奇）误说成 for curiosity，介词固定用 out of。","u":"「出于好奇」用 out of curiosity，介词不用 for。"},
  "curious": {"c":["curious about the world","a curious look","curious to know","strangely curious","curious coincidence"],"b":"curious 源自拉丁语 curiosus，本义是「仔细的、爱打听的」，与 care（关心）同源。它有两层含义：一是「好奇的」，二是「奇怪的」，后者常被中国学习者忽略。注意搭配介词：对某事好奇用 curious about，而「想知道」则用 curious to do，两者不可互换。","u":"对某事好奇用 be curious about；「想知道」用 be curiou"},
  "debatable": {"u":"指尚无定论；常用 it is debatable whether..."},
  "decisive": {"u":"既指决定性的，也指果断的。"},
  "decline": {"c":["decline an invitation","a sharp decline in","decline to comment","economic decline","on the decline"],"b":"decline 源自拉丁语 declinare，由 de-（向下）加 clinare（倾斜）构成，本义是「向下弯」，因此引申出「下降」和「婉拒」两义。婉拒义比 refuse 更礼貌委婉，常用于正式场合，如 decline an invitation。中国学习者常只知道「下降」，忽略了「礼貌拒绝」这一高频用法。","u":"表示「婉拒」时比 refuse 更礼貌正式，常用 decline an invi"},
  "dedicate": {"c":["dedicate oneself to","dedicate one's life to","dedicate time to","dedicate a book to","be dedicated to"],"b":"源自拉丁语 dedicare，本义是「郑重宣告、奉献给神明」，de-（彻底）+ dicare（宣告）。因此 dedicate 带有庄重、正式的仪式感，常用于把一生、精力献给某项事业。中国学习者常误把它当 give 的普通替换，其实它强调「郑重投入」，宾语多为 life、time、effort 等抽象物，且常用 dedicate oneself to doing 结构。","u":"dedicate A to B：把 A 奉献给 B；to 为介词，后接名词或动名"},
  "defense": {"u":"in defense of 表为…辩护；英式拼作 defence。"},
  "delightful": {"c":["a delightful surprise","delightful to watch","absolutely delightful","delightful little café","find it delightful"],"b":"源自古法语 delit（愉悦），与 delicate（精致的）同源，本义是「使人产生强烈快感」。中国学习者常把它和 delicious 混用：delicious 只形容食物味道好，delightful 则用于经历、人、天气、消息等一切令人愉悦的事物，如 a delightful evening。","u":"形容人、经历、天气等令人愉快，不用于食物味道。"},
  "deport": {"u":"特指将外国人依法驱逐出境；名词 deportation。"},
  "deposit": {"c":["make a deposit","pay a deposit","a security deposit","deposit money in the bank","mineral deposits"],"b":"源自拉丁语 deponere（放下），de-（向下）加 ponere（放置），本义是「把东西放下」，于是有了「存放、存款、沉积」等义。租房时交的押金也叫 deposit。中文学习者常混淆 deposit 与 down payment：deposit 多为定金或押金，down payment 指分期付款的首付。","u":"租房押金、银行存钱均可用；首付宜用 down payment。"},
  "deprive": {"u":"固定搭配 deprive sb of sth；常用被动 be deprived"},
  "desperate": {"u":"本义失去希望；引申为铤而走险的。"},
  "destruction": {"c":["cause destruction","the destruction of forests","mass destruction","environmental destruction","complete destruction"],"b":"destruction 来自拉丁语 destruere（拆毁），de-（向下、去掉）+ struere（建造），字面是「把建起来的东西拆掉」，与 construction（建造）正好相反。它多指大规模、彻底的破坏，如 weapons of mass destruction。中国学习者常把它与 damage 混用，damage 可数且程度较轻。","u":"destruction 多指彻底破坏，不可数；damage 可数且程度较轻。"},
  "diagnosis": {"u":"复数为 diagnoses；make a diagnosis 指作出诊断。"},
  "dialogue": {"c":["open a dialogue with","a dialogue between","meaningful dialogue","dialogue box","engage in dialogue"],"b":"dialogue 源自希腊语 dialogos，由 dia-（之间）加 logos（言语、理性）构成，本义是「人与人之间的交谈」。它比 conversation 更正式，常指有目的的对话，甚至用于国家间的「对话」。中国学习者容易把它只理解为「对白」，其实它在政治、商务语境中表示「沟通协商」也很常见。","u":"指正式对话或戏剧对白；与某人对话用 with。"},
  "dictate": {"u":"既指口述，也指形势、规则支配决定。"},
  "did": {"c":["did well in","did my best","did the dishes","did some research","did a good job"],"b":"did 是 do 的过去式，源自古英语 dydon。中国学习者最常见的误用是助动词与实义动词混用，如把 did 后面再接过去式，说成 did went、did ate，其实助动词 did 后必须跟动词原形，如 did go、did eat。"},
  "didn": {"c":["didn't know","didn't mean to","didn't use to","didn't have to","didn't see it coming"],"b":"didn 是 did not 的口语缩略形式，常见于 didn't。中国学习者常犯的错误是双重否定，如 I didn't do nothing，标准英语应为 I didn't do anything。另外 didn't use to 表示“过去不常”，注意 use 的拼写而非 used。"},
  "discipline": {"u":"作「纪律」不可数；作「学科」可数，如 a discipline。"},
  "discredit": {"u":"使失去信任或败坏名声；名词指耻辱。"},
  "disgraceful": {"u":"语气强，指令人愤慨的可耻行为。"},
  "dispute": {"u":"settle a dispute 指解决争端；in dispute 表有争议。"},
  "divide": {"u":"divide...into 分成；divide by 除以。"},
  "don": {"c":["don a coat","don a hat","don formal attire","don a mask"],"b":"don 作「穿上」讲时源自古英语 dōn（做），与 do 同源，是较文雅或戏谑的用法，常见于 don a coat/hat。但中国学习者更常遇到的是缩合形式 don't，即 do not，此时 don 只是 do 的变体，切勿把 don't 拆成 don 加 t 来理解。"},
  "donation": {"u":"捐款用 make a donation to，动词不用 do。"},
  "dormitories": {"u":"单数为 dormitory，口语常缩为 dorm；指学生宿舍。"},
  "down": {"c":["sit down","go down the stairs","turn down the music","down the street","ups and downs"],"b":"down 源自古英语 dūne，本是「从高处往低处」的意思，与 up 相对。它既可作副词（sit down），也可作介词（walk down the street）。中国学习者容易混淆 down 与 under：down 强调「向下」的动态方向，under 强调「在……下面」的静态位置。turn down 除「调小」外还可表示「拒绝」，是考试高频短语。"},
  "during": {"u":"后接名词，不接从句；接从句用 while。"},
  "eccentric": {"u":"指古怪的、不合常规的；名词指怪人。"},
  "ecology": {"u":"指生态或生态学；与 environment 侧重点不同。"},
  "economics": {"u":"作学科名视为单数；study economics 指学经济学。"},
  "ecosystem": {"u":"指生物与环境构成的整体，20 世纪生态学新造词。"},
  "elevate": {"u":"较正式；既指抬高物体，也指提升地位、情绪。"},
  "eloquent": {"u":"可形容人雄辩，也可形容事物极具表现力。"},
  "emit": {"u":"及物动词，指发出光、热、声音、气体等。"},
  "empathy": {"c":["show empathy for","have empathy with","deep empathy","lack empathy","empathy towards others"],"b":"由希腊语 em-（在内）+ pathos（感受）构成，20 世纪初由心理学家铁钦纳借译德语 Einfühlung 引入英语，本义是「把自己的感受投射进对象」。中国学习者常与 sympathy（同情）混用：empathy 强调「设身处地体会对方感受」，sympathy 侧重「对他人不幸的怜悯」。","u":"empathy 重在感同身受，sympathy 重在同情怜悯，勿混。"},
  "emphasize": {"c":["emphasize the importance of","strongly emphasize","emphasize that clause","emphasize the need for","repeatedly emphasize"],"b":"来自希腊语 emphasis（显现、强调），em-（在内）+ phainein（显示）。它既可接名词，也可接 that 从句，表示「强调某一事实」。英式英语常拼作 emphasise。中国学习者常见误用是 emphasize on sth，受汉语「强调在……」影响；正确说法是 emphasize sth，不加 on。","u":"emphasize 后直接跟宾语，不要加 on；名词形式为 emphasis。"},
  "endless": {"c":["endless possibilities","an endless supply","endless debate","seem endless","endless patience"],"b":"由 end（尽头）加后缀 -less（无……的）构成，字面即「没有尽头的」。它既可指空间时间上的无穷，也常带贬义，表示「没完没了的」，如 endless meetings。中国学习者有时误用为「无限的褒义」，其实在口语中它常含抱怨语气，需根据语境判断褒贬。","u":"常带贬义，指没完没了、令人厌烦。"},
  "energy": {"c":["save energy","renewable energy","full of energy","solar energy","waste energy"],"b":"energy 源自希腊语 energeia（活动、作用），由 en-（在内）+ ergon（工作）构成，本义“内在的做功能力”。物理上指能量，日常也指精力。中国学习者常说 I have no energy to do，注意 to do 前不加 for，且 energy 作“精力”时不可数。","u":"指能量或精力，不可数；常用 be full of energy 形容精力充沛。"},
  "error": {"u":"比 mistake 更正式，多指计算或技术上的偏差。"},
  "evaluate": {"u":"指按标准评估，常接 performance、impact 等。"},
  "even": {"c":["even better than before","even if it rains","even more difficult","not even once","even so, I agree"],"b":"作副词时 even 表示「甚至」，作用是强调句中某个成分，通常紧挨着被强调的词。中国学习者常把它误放在句首或随意位置，例如把 Even I don't like it 与 I don't even like it 混为一谈——前者强调「连我都不喜欢」，后者强调「我甚至不喜欢」。位置不同，语义重心完全不同。"},
  "events": {"u":"复数常指时事或系列事件，如 current events。"},
  "evident": {"c":["it is evident that","become evident","clearly evident","evident from the data","self-evident truth"],"b":"来自拉丁语 evidens，e-（向外）+ videre（看），字面意思是「一看就看得出来的」。所以它比 obvious 更强调「由证据显现出来」，常用于学术与正式书面语，如 it is evident from the results that...。中国学习者易与 evidence（证据）混用：evident 是形容词，evidence 是不可数名词，不能写 an evident。","u":"常用 it is evident that... 句型，较正式。"},
  "exclaim": {"u":"因惊讶等突然喊出；exclaim at/in/with sth。"},
  "exempt": {"u":"形容词后接 from；动词用 exempt sb from sth。"},
  "expand": {"u":"expand on 表详细阐述；expand into 表扩展进入。"},
  "export": {"c":["export goods","export to Europe","oil exports","export license","main export market"],"b":"export 由 ex-（向外）+ port（携带）构成，与 transport、import 同源，字面即“运出去”。作名词时重音在前，作动词时重音在后。中国学习者易混淆 export 与 exportation：日常表达出口业务时用 exports 复数更自然，如 oil exports。","u":"作动词重音在后，作名词重音在前；常用 export to + 地点。"},
  "expose": {"c":["expose to the sun","expose the truth","be exposed to","expose a scandal","expose children to music"],"b":"expose 源自拉丁语 exponere，由 ex-（向外）加 ponere（放置）构成，字面就是「放出来、摆出来」，所以既有「暴露」也有「揭露」之义。中国学习者最常忽略的是 be exposed to 这一被动结构，它表示「接触到、暴露于」，如 be exposed to different cultures，是阅读中的高频考点。","u":"be exposed to 表示「接触到、暴露于」，是高频被动搭配，注意 to "},
  "extensive": {"u":"强调范围广、数量大；与 intensive 相对。"},
  "false": {"u":"强调不真实；false alarm 指虚惊，false teeth 指假牙。"},
  "familiar": {"u":"人用 be familiar with，物用 be familiar to。"},
  "fearless": {"u":"褒义，指无所畏惧、勇敢，非鲁莽。"},
  "feminist": {"u":"名词指女性主义者，形容词指女性主义的。"},
  "ferdinand magellan": {"u":"葡萄牙航海家，率队首次环球航行。"},
  "fertile": {"u":"既指土地肥沃，也指想象力丰富。"},
  "fifteen": {"u":"拼写为 fifteen，不是 fiveteen。"},
  "figure": {"u":"figure out 表弄明白；public figure 指公众人物。"},
  "file": {"u":"file a complaint 指提出投诉；in single file"},
  "flawless": {"u":"指找不出瑕疵；多形容表演、皮肤、逻辑。"},
  "for": {"c":["wait for me","thanks for your help","for example","for a long time","look for a job"],"b":"for 源自古英语 for，本义是“在前面、为了”，后来引申出目的、原因、时间持续、对象等多种含义。它既可作介词，也可作并列连词（表原因，较正式）。中国学习者常混淆 for 与 to：for 后接名词或动名词，to 后接动词原形，如 I came here for seeing you 应改为 to see you。"},
  "forefront": {"u":"固定用 at the forefront of，指处于最前列。"},
  "fourteen": {"u":"拼写不含 u，与 four 不同，是常见拼写易错点。"},
  "fragile": {"u":"既指物品易碎，也指局势、健康脆弱。"},
  "freedom": {"u":"freedom of 有做某事的自由；freedom from 免于。"},
  "from": {"c":["from now on","come from China","from time to time","different from","far from easy"],"b":"from 源自古英语 fram，本义是「向前、离开」。常见误用是混淆 from 与 since：from 只表示起点，搭配现在完成时要用 since，如 I have lived here since 2010，不能说 from 2010。"},
  "frustrate": {"u":"frustrated 修饰人，frustrating 修饰事。"},
  "generate": {"c":["generate electricity","generate income","generate interest","generate new ideas","generate a lot of heat"],"b":"源自拉丁语 generare（生育、产生），词根 gen- 与「出生、种类」有关，同族词有 gene、genesis。它强调通过某种过程产生出结果，常见搭配是 generate electricity/income/interest。中文学习者易与 produce 混用，generate 更偏「引发、催生」抽象事物。","u":"多接 electricity、income、interest 等，偏引发抽象事物"},
  "generous": {"c":["be generous with money","a generous offer","generous to a fault","a generous portion","generous support"],"b":"源自拉丁语 generosus，本义是「出身高贵的」，古人认为贵族才具备慷慨大方的品质，词义由此演变而来。注意它还有「大量的、丰盛的」义，如 a generous portion（分量很足）。中文学习者常只知道「慷慨」，忽略这一引申义。","u":"除慷慨外还表「大量的」，如 a generous portion。"},
  "genghis khan": {"u":"蒙古帝国创建者，本名铁木真。"},
  "genius": {"c":["a genius for","musical genius","a stroke of genius","genius at math","recognize sb's genius"],"b":"genius 源自拉丁语，本义是罗马神话中守护人的“精灵”，后引申为与生俱来的天赋。中国学习者常误说 He is genius，漏掉冠词；正确是 He is a genius。表示“在某方面有天赋”用 a genius for sth 或 a genius at doing sth。","u":"可数名词，须加冠词；a genius for sth 表示某方面的天赋。"},
  "genuine": {"c":["genuine interest","genuine leather","a genuine smile","genuine concern","genuine article"],"b":"源自拉丁语 genuinus，本义是「天生的、天然的」，与「人造、假冒」相对，因此既指物品「真品」，也指情感「真诚」。中国学习者常把 genuine 与 real 混用：real 强调「真实存在」，genuine 强调「非伪造、非虚伪」，如 genuine leather（真皮）、a genuine smile（真诚的微笑）。","u":"既指物品「真货」，也指情感「真诚」。"},
  "geography": {"c":["study geography","physical geography","human geography","the geography of the region","a geography lesson"],"b":"由希腊语 geo-（大地）加 -graphy（书写、描述）构成，字面即「对大地的描述」。同前缀词还有 geology（地质学）、geometry（几何）。中文学习者易把它与 geology 混淆：geography 研究地表分布与人文现象，geology 研究岩石与地球内部构造。","u":"区别于 geology，geography 侧重地表与人文分布。"},
  "giacometti": {"u":"瑞士雕塑家，以细长人形雕塑著称。"},
  "glory": {"u":"glory days 指辉煌岁月；win glory 表赢得荣誉。"},
  "going": {"c":["going to school","keep going","going on vacation","going well","going through hard times"],"b":"going 是 go 的现在分词，源自古英语 gan。be going to 表示计划或预测，与 will 略有区别：前者偏重事先打算，后者偏重临时决定。中国学习者易把 be going to 后误接动名词，如 going to swimming。"},
  "gonna": {"c":["gonna be","gonna do","gonna get","gonna have","gonna go"],"b":"gonna 是 going to 的口语缩略，19 世纪起在美式英语中流行。它只用于非正式口语，不能出现在正式写作中。中国学习者常误把它当作独立动词，其实它后面必须接动词原形，且不能与 be 动词分开使用。"},
  "got": {"c":["got it","have got","got to go","got married","got a minute"],"b":"got 是 get 的过去式和过去分词，源自古诺斯语 geta。英式英语中 have got 表示「拥有」，相当于美式的 have。中国学习者常误用 got 的时态，如把 I got it 当作一般现在时，其实它表示「我明白了」或「我拿到了」，是过去动作。got to 在口语中等于 have to，表示「必须」，但较随意。"},
  "graphic": {"c":["graphic design","graphic novel","graphic violence","graphic details","a graphic description"],"b":"源自希腊语 graphein（书写、刻画），本义与「图画、文字」相关。现代英语中它有两层含义：一是「图形的」，如 graphic design；二是「逼真到令人不适的」，如 graphic violence。中国学习者常忽略第二层，看到 graphic 就只想到「图表」，其实 the graphic details 指血淋淋的细节。","u":"既可指图形的，也可指描写逼真露骨，注意语境。"},
  "had": {"c":["had better","had to go","had a good time","had no idea","had already finished"],"b":"had 是 have 的过去式和过去分词。had better 是固定搭配，后接动词原形，表示“最好”，如 You had better rest，不能说 had better to rest。此外 had 常用于过去完成时，表示“过去的过去”，中国学习者容易忽略它与一般过去时的区别。"},
  "hardware": {"u":"指硬件或五金；hardware store 指五金店。"},
  "harmonic": {"u":"指和谐的、和声的；常用于音乐、物理。"},
  "has": {"c":["has to go","has been","has got","has no idea","has a point"],"b":"has 是 have 的第三人称单数形式。中国学习者常混淆 has been to 与 has gone to：前者表示“去过已回”，后者表示“去了未回”。另外 has got 在英式英语中常代替 has，表示“有”，口语中很常见。"},
  "have": {"c":["have a good time","have breakfast","have to go","have a look","have a headache"],"b":"have 源自古英语 habban，本义是“持有、拥有”，后来扩展出“吃、喝、进行、经历”等大量用法，如 have lunch、have a meeting。它还可作助动词构成完成时。中国学习者要注意 have to 表示“不得不”，与 must 意思相近但更强调客观需要，且 have to 的否定和疑问要借助 do。"},
  "he": {"c":["he is my brother","he works hard","he said so","he and I","does he know"],"b":"he 是第三人称单数阳性主格代词，源自古英语 hē，与德语 er 同源。它作主语，宾格是 him，形容词性物主代词是 his。中国学习者要注意，指代动物或婴儿时英语有时也用 he 或 she，而汉语常用“它”，这是拟人化习惯的差异。另外 he 在一般现在时中动词要加 -s。"},
  "hepworth": {"u":"英国雕塑家，以穿孔抽象石雕著称。"},
  "her": {"u":"作所有格后接名词，作宾格作宾语，靠后接成分判断。"},
  "here": {"c":["here you are","here and there","here we go","come here please","here is the problem"],"b":"here 源自古英语 hēr，与 there 相对，表示「这里」。它常用于倒装句，如 Here comes the bus，此时主语是名词才倒装，若主语是代词则不倒装，说 Here it comes。中国学习者易错说 Here comes it，需注意这一区别。"},
  "hey": {"c":["hey there","hey you","hey man","say hey to","hey, wait a minute"],"b":"hey 是自然感叹词，中古英语时期就已出现，最初用来引起注意或表示惊讶。它比 hi 更随意，常用于熟人之间。中国学习者要注意 hey 在正式场合或对长辈使用可能显得不礼貌，应改用 excuse me 或 hello。"},
  "him": {"c":["give him a call","tell him the truth","with him","ask him for help","I like him"],"b":"him 源自古英语 him，是 he 的与格形式，后来兼作宾格。它与 she 的宾格 her 不同，her 同时还是所有格，而 him 只作宾语，其所有格是 his。中国学习者常犯的错误是在介词后误用 he，如 with he，正确应为 with him。另外在口语中 him 可弱读，但书写时不能省略。"},
  "his": {"c":["his own car","his best friend","in his opinion","his first time","on his way"],"b":"his 源自古英语 his，是 he 的属格形式。常见误用是把 his 与 him 混淆：his 后必须接名词，him 作动词或介词的宾语，如 his book 不能说 him book，而 I saw him 不能说 I saw his。"},
  "hopeless": {"c":["a hopeless case","feel hopeless about","hopeless at maths","utterly hopeless","a hopeless romantic"],"b":"由 hope 加否定后缀 -less 构成，字面即「没有希望的」。除了「绝望的」，口语中它还常表示「极差的、无可救药的」，如 I'm hopeless at cooking（我做饭糟透了）。中国学习者容易只记「绝望」一义，听到 a hopeless romantic 会误以为是贬义，其实指「无可救药的浪漫主义者」。","u":"可表绝望，也可口语中表「极差、无可救药」。"},
  "houdon": {"u":"法国雕塑家，以名人肖像胸像著称。"},
  "how": {"c":["how are you","how about you","how much","how long","how come"],"b":"how 源自古英语 hū，与德语 wie 同源，本义是「以什么方式」。它可引导疑问句和感叹句，如 How beautiful! 中国学习者常混淆 how 与 what 引导的感叹句：how 修饰形容词或副词，what 修饰名词。另外 how come 是口语中「为什么」的非正式说法，后接陈述语序，不用倒装。"},
  "human": {"u":"human rights 指人权；human nature 指人性。"},
  "ibn battuta": {"u":"摩洛哥旅行家，游历亚非多地并留下游记。"},
  "if": {"c":["if you like","if it rains","if I were you","if possible","if only"],"b":"if 源自古英语 gif，与德语 ob 同源，本义是「在……条件下」。中国学习者最大的误区是把「是否」义的 if 用于宾语从句时与 whether 混用：介词后、不定式前只能用 whether，不能说 depend on if。此外 if 引导的条件句遵循「主将从现」，即主句用将来时、从句用一般现在时，这是汉语没有的规则。"},
  "illicit": {"u":"比 illegal 更强调违反道德；illicit drugs 指违禁毒品。"},
  "illuminate": {"u":"既指照亮，也指阐明问题、说明道理。"},
  "imagination": {"c":["use your imagination","a vivid imagination","capture the imagination","beyond imagination","lack imagination"],"b":"imagination 源自拉丁语 imaginatio，词根 imago 意为「图像」，所以它的核心是「在头脑中形成图像的能力」。中国文化中常把「想象力」与「幻想」混同，其实英语里 imagination 偏褒义，指创造力；而 fantasy 才偏指脱离现实的幻想。capture the imagination 意为「激发想象力」，是地道表达。","u":"常用 capture one's imagination 表「引人遐想」。"},
  "immortal": {"u":"由 im- + mortal 构成，指不朽的、永生的。"},
  "immune": {"u":"immune to 对…免疫/不受影响；immune from 免受。"},
  "impose": {"c":["impose a tax on","impose restrictions on","impose one's views on","impose a fine","impose on someone"],"b":"源自拉丁语 imponere，in-（在上）+ ponere（放置），本义是「把东西放在上面」，引申为「强加、征收」。常用结构 impose sth on sb，表示把某物强加于人。中国学习者易漏掉介词 on，写成 impose sb sth；正确搭配必须用 impose A on B，注意语序与介词。","u":"impose A on B：把 A 强加于 B；被动为 be imposed o"},
  "impress": {"c":["impress the audience","be impressed by","impress on someone","impress upon the mind","deeply impressed"],"b":"impress 源自拉丁语 imprimere，由 in-（进入）加 premere（压）构成，本义是「压印、盖章」，所以引申为「在心上留下印记」。中国学习者常混淆 impress 与 be impressed：前者是「使别人印象深刻」，后者是「自己被感动」。impress on/upon 则表示「使铭记」，宾语常是抽象道理。","u":"impress sb 是「使别人印象深刻」；be impressed by 是「"},
  "in": {"c":["in the morning","in China","in fact","in a hurry","interested in music"],"b":"in 本义是“在里面”，与 into 同源，强调处于某个空间或状态之中。它还可表示时间范围、方式、领域等。中国学习者常混淆 in 与 on、at 的时间用法：in 用于较长时段（in 2024、in May），on 用于具体某天，at 用于具体时刻。记住“大 in、小 at、具体某天用 on”即可。"},
  "incredible": {"c":["an incredible story","incredibly beautiful","incredible speed","hard to believe but incredible","absolutely incredible"],"b":"incredible 由拉丁语 in-（否定）加 credere（相信）构成，字面就是「不可相信的」，与 credit、creed 同源。它有两层意思：一是「难以置信的」，二是口语中表示「极好的」，如 incredible food。中国学习者常只记住第一义，遇到口语中表示赞叹的用法时容易误解为「假得离谱」。","u":"口语中常表示「极好的」而非「不可信的」，需根据语境判断褒贬。"},
  "indicative": {"u":"be indicative of 表表明、暗示，为最常用搭配。"},
  "individual": {"u":"强调单个个体，与集体相对；也作名词。"},
  "induce": {"c":["induce sb to do sth","induce sleep","induce labor","induce vomiting","drug-induced"],"b":"来自拉丁语 inducere（in-「进入」+ ducere「引导」），字面即「领进去」，故有「诱导、引起」两义。医学上 induce labor（引产）、induce sleep（催眠）都很常见。注意它与 deduce（演绎）、seduce（引诱）共享 -duc- 词根，但方向不同：induce 是「引入」，deduce 是「导出」。","u":"常用 induce sb to do sth；医学中 induce labor "},
  "inevitable": {"c":["an inevitable consequence","seem inevitable","accept the inevitable","almost inevitable","the inevitable result"],"b":"源自拉丁语 in-（不）+ evitare（避免），字面就是「无法避免的」。它常与 the 连用名词化，the inevitable 指「不可避免之事」。中国学习者常误写成 inevitible 或 inevitable 后接 to do，正确搭配是 be inevitable that 从句或直接作定语，如 It was inevitable that he would fail。","u":"常用句式 It is inevitable that...，不加 to do。"},
  "infer": {"c":["infer from evidence","infer a conclusion","reasonably infer","infer meaning from context","be inferred from"],"b":"拉丁语 inferre 意为「带入、推出」，由 in-（向内）+ ferre（携带）构成。常见误用是把它当成 imply 的同义词：严格说，说话人 imply（暗示），听者 infer（推断），方向相反。阅读理解题干里 infer 常译「推断」，答案须是文中未直说但可推出的信息。","u":"说话人 imply 暗示，听者 infer 推断，方向相反勿混用。"},
  "infrastructure": {"u":"指道路、电网等基础设施，通常不可数。"},
  "insistent": {"u":"be insistent on 表坚持要求；语气比 insist 更强调。"},
  "instruct": {"c":["instruct sb to do","instruct students","instruct in English","instruct sb on sth","carefully instructed"],"b":"instruct 源自拉丁语 instruere（构建、装备），本义“在头脑中搭建知识”，故既指“教导”，也指“指示、命令”。中国学习者易与 teach 混：instruct 更强调系统训练或明确指令，常用 instruct sb to do sth 表示吩咐某人做某事。","u":"常用 instruct sb to do sth；表示“指示”时比 teach "},
  "insulation": {"u":"指隔热、绝缘或隔离；动词 insulate。"},
  "integrity": {"u":"不可数；指人品正直或事物完整。"},
  "intention": {"u":"常用 have no intention of doing 或 with"},
  "interval": {"c":["at regular intervals","a short interval","during the interval","at intervals of ten minutes","a brief interval"],"b":"源自拉丁语 intervallum，由 inter（之间）+ vallum（墙、壁垒）构成，本指两墙之间的空隙，后引申为时间或空间上的间隔。英式英语中 the interval 特指戏剧、音乐会的中场休息，美式则多说 intermission。中国学习者常把 at intervals 误用为 in intervals，固定搭配是 at regular intervals。","u":"固定搭配 at intervals，不写 in intervals。"},
  "intervene": {"u":"指介入干预；常用 intervene in sth。"},
  "invade": {"u":"本指军事入侵，也指涌入、侵犯隐私。"},
  "involvement": {"u":"常接 in：involvement in 表参与或卷入某事。"},
  "is": {"c":["he is a teacher","there is a book","is it ready","the weather is nice","this is my friend"],"b":"is 是 be 动词的第三人称单数现在式，源自古英语 is，与德语 ist、拉丁语 est 同源。它既作系动词连接主语和表语，也作助动词构成进行时和被动语态。中国学习者最常漏掉它，因为汉语说“他是老师”没有对应的系动词，英语却必须说 He is a teacher。"},
  "it": {"c":["it is raining","make it clear","take it easy","it depends on","find it hard"],"b":"it 源自古英语 hit，后来 h 脱落才变成今天的 it。它最特别之处是能作“形式主语”和“形式宾语”：真正的主语或宾语放到句子后面，前面用 it 占位，如 It is important to learn English。中国学习者常漏掉这个占位 it，说成 Is important to...，这是最典型的误用。"},
  "joan of arc": {"u":"法国民族英雄，率军解奥尔良之围后被烧死。"},
  "journalist": {"c":["a political journalist","investigative journalist","freelance journalist","a journalist for the BBC","journalist and broadcaster"],"b":"源自法语 journal（日报），词根是拉丁语 diurnalis（每日的），本义是「写日报的人」。因此 journalist 指新闻从业者，与汉语「记者」基本对应。注意它与 reporter 的细微差别：journalist 更强调采写、评论的专业身份，reporter 多指外出采访的记者。","u":"泛指记者、新闻工作者，含各媒体。"},
  "julius caesar": {"u":"古罗马统帅与独裁官，后被刺杀。"},
  "jurisdiction": {"u":"指管辖权；have jurisdiction over 对……有管辖权。"},
  "jury": {"c":["serve on a jury","a jury of twelve","the jury reaches a verdict","a grand jury","trial by jury"],"b":"源自拉丁语 jurare（宣誓），本义是「宣誓的人」，与 judge、justice 同源。英美法系中陪审团由普通公民组成，负责认定事实，法官负责适用法律。中文学习者常误以为 jury 也负责量刑或判案，其实它主要裁定有罪与否。","u":"陪审团只裁定事实与是否有罪，不负责量刑。"},
  "just": {"c":["just a moment","just in time","just as I thought","just about ready","just between us"],"b":"just 源自拉丁语 iustus（公正的），本义是「合乎正义的」，后引申为「正好、仅仅」。中国学习者常混淆 just 与 only：just 强调「恰好、刚刚」，only 强调「仅仅、唯一」。在完成时中 just 表示「刚刚」，如 I have just finished。"},
  "justify": {"c":["justify the decision","justify oneself","justify the means","hard to justify","justify spending money"],"b":"justify 源自拉丁语 justus（公正）+ facere（做），本义“使变得公正”，故指证明某事正当。中国学习者易误用 justify to do，正确结构是 justify doing sth 或 justify sth，如 justify spending so much money。","u":"后接动名词或名词，不接不定式；justify doing sth 是常见结构。"},
  "kahlo": {"u":"墨西哥女画家，以自画像与民族色彩著称。"},
  "kilometer": {"u":"英式拼作 kilometre；常缩写为 km。"},
  "kilometre": {"u":"英式拼写；缩写 km，常搭 per hour"},
  "kingdom": {"u":"指王国，也指生物分类的「界」或领域。"},
  "let": {"c":["let me know","let go of","let it be","let me in","let us go"],"b":"let 源自古英语 lætan，本义是「允许、放任」。最大陷阱是使役结构：let 后接宾语再加动词原形，不能加 to，如 let him go，中国学习者常误说成 let him to go，因为受 tell sb. to do 的类推影响。"},
  "librarian": {"u":"由 library + -ian 构成，指图书管理员。"},
  "like": {"c":["like to do","like doing","look like","feel like doing","would like to"],"b":"like 作动词源自古英语 līcian（使高兴），本义是「使……愉悦」，所以「喜欢」是引申义；作介词时源自古英语 gelīc（相似的），表示「像」。中国学习者常混淆 like to do 与 like doing：前者偏具体一次性喜好，后者偏长期习惯爱好。"},
  "litigation": {"u":"不可数，指诉讼；civil litigation 民事诉讼。"},
  "little": {"c":["a little bit","little by little","a little water","little children","quite a little"],"b":"little 源自古英语 lȳtel，本义是「小的」，后引申出「少的」。它最微妙之处在于有无冠词意思相反：a little 表示「有一点」（肯定），little 表示「几乎没有」（否定）。中国学习者常把 a little 与 a few 弄混：a little 修饰不可数名词，a few 修饰可数名词复数。little by little 意为「一点一点地」。"},
  "location": {"u":"on location 指外景实拍，非「在位置」"},
  "logic": {"c":["follow the logic","a matter of logic","the logic behind the decision","sound logic","by the logic of"],"b":"源自希腊语 logos（言语、理性），经拉丁语进入英语，本义是「推理的学问」。中文学习者易受汉语「逻辑」影响，把它只当名词，其实英语中还有形容词 logical、副词 logically。注意 logic 作「条理」时常不可数，如 There is no logic in it。","u":"作「条理、道理」时不可数，如 no logic in it。"},
  "longitudinal": {"u":"指纵向的、经度的；常见 longitudinal study。"},
  "major": {"u":"作形容词指主要的；作动词 major in 主修。"},
  "manuscript": {"u":"指手稿、原稿；submit a manuscript 指投稿。"},
  "marco polo": {"u":"意大利旅行家，元朝游历中国并著行纪。"},
  "marine": {"u":"marine biology 海洋生物学；the Marines 海军陆战队"},
  "maternal": {"u":"maternal grandmother 指外祖母，非祖母"},
  "me": {"c":["give me a hand","excuse me","it's me","tell me the truth","between you and me"],"b":"me 是 I 的宾格形式，源自古英语 mē，与德语 mich 同源。它在句中作动词或介词的宾语。中国学习者最容易犯的错是在并列结构中用错格，如说 between you and I，正确应为 between you and me，因为介词后必须用宾格。口语中 It's me 虽不合传统语法，却已被广泛接受。"},
  "meaningless": {"u":"由 meaning + -less 构成，意为无意义、无价值。"},
  "memorize": {"u":"指有意背诵记住；与 remember（记得）不同。"},
  "microchip": {"u":"micro- 表微小；可作动词指植入芯片"},
  "microphone": {"u":"指话筒；对着话筒说用 into the microphone。"},
  "microscope": {"u":"under the microscope 引申为受严密审视"},
  "midday": {"u":"用 at midday；比 noon 更口语、时段更宽。"},
  "military": {"c":["military service","military action","military personnel","join the military","military training"],"b":"源自拉丁语 miles（士兵），本义与「当兵」相关。作形容词指「军事的」，作名词 the military 指「军队、军方」这一整体。中国学习者常混淆 military 与 army：army 多指陆军或某支军队，military 更广，涵盖陆海空各军种及军事事务，如 military service（兵役）。","u":"作名词 the military 指军队整体，不特指陆军。"},
  "millennium": {"u":"一千年；复数为 millennia，注意双 l 双 n。"},
  "misfortune": {"u":"由 mis- + fortune 构成，指不幸、厄运。"},
  "misleading": {"u":"修饰信息、说法等，指易使人误解的。"},
  "missile": {"c":["launch a missile","a guided missile","missile defence system","fire a missile","a nuclear missile"],"b":"源自拉丁语 mittere（发送、投掷），本义是「被投掷出去的东西」，所以标枪、石块都曾是 missile。20 世纪后专指导弹、飞弹。注意它与 missile 同源的 mission（使命）、emit（发出）都含「送出去」之意。中国学习者易把它和 bullet（子弹）混淆，missile 是自带推进、可制导的大型飞行武器。","u":"指导弹等大型投射武器，不指普通子弹。"},
  "misunderstand": {"c":["misunderstand the question","completely misunderstand","misunderstand each other","easy to misunderstand","misunderstand his intention"],"b":"由前缀 mis-（错误地）+ understand 构成，是规则派生词，过去式和过去分词都是 misunderstood。中国学习者常犯的错误是把它当成不规则动词，编出 misunderstanded 这种形式。它强调「理解错了」，而 not understand 只是「没听懂」，两者语气不同：Don't misunderstand me 是「别误会我」。","u":"过去式、过去分词均为 misunderstood，不写 misunderstan"},
  "moderate": {"u":"可作动词，指主持、调节（辩论等）"},
  "monologue": {"u":"指独白；日常常含贬义，指一人长篇大论。"},
  "monoware": {"c":["disposable monoware","monoware products","a piece of monoware","replace plastic monoware","monoware ban"],"b":"monoware 是 mono-（单一）与 -ware（器皿、制品）组合的新造词，仿照 software、hardware 的构词方式，指用完即弃、只供一次性使用的餐具。它是环保语境下的生造词，尚未广泛进入通用词典，多出现在可持续消费与减塑话题的讨论中。","u":"多用于环保语境，指一次性餐具；正式写作中常被 disposable tablew"},
  "monument": {"u":"a monument to 后接抽象名词表「见证」"},
  "moore": {"u":"英国雕塑家，以斜倚人像与母子题材著称。"},
  "more": {"c":["more and more people","more than enough","no more than","more or less","what's more"],"b":"more 源自古英语 māra，是 much/many 的比较级，本义就是「更多」。中国学习者最常犯的错是把它当成 many 的普通替换，说成 many more 时又漏掉可数/不可数的区分：修饰可数名词复数用 more books，修饰不可数名词用 more water，两者都可以。另外 more than 后接数词表示「超过」，no more than 则是「仅仅」，语气差别很大。"},
  "mortal": {"c":["a mortal enemy","mortal danger","mortal remains","mere mortals","mortal fear"],"b":"源自拉丁语 mors（死亡），本义「会死的」。在西方文化中它与 immortal（不朽的）相对，神是不朽的，人是 mortal，所以 mere mortals 指「区区凡人」。作形容词时它还表示「致命的、不共戴天的」，如 mortal enemy（死敌）。中国学习者易只记「凡人」一义，忽略其「致命、极度」的引申用法。","u":"作名词指凡人；作形容词可表致命、不共戴天。"},
  "mortality": {"u":"指死亡率；infant mortality 婴儿死亡率。"},
  "mortals": {"u":"常与神对比，mere mortals 指区区凡人"},
  "mortgage": {"c":["pay off the mortgage","take out a mortgage","a mortgage on the house","monthly mortgage payments","mortgage rates"],"b":"源自古法语 mort（死）+ gage（抵押），本义是「死契」——若债务到期不还，抵押物即永久归债权人，契约「死去」。这个词生动记录了中世纪借贷文化。中国学习者常混淆 mortgage 与 loan：loan 是泛指贷款，mortgage 特指以房产等不动产作担保的购房贷款。","u":"特指以房产作抵押的贷款，不泛指一切贷款。"},
  "much": {"c":["much more than expected","too much water","how much money","much better now","not much time left"],"b":"much 源自古英语 mycel，本义是「大的、多的」，后来专指数量的「多」。它最大的特点是修饰不可数名词，这与 many 修饰可数名词形成对照，是中国学习者最经典的混淆点之一。此外 much 还常作副词修饰比较级，如 much better，此时不能用 very 替换。"},
  "my": {"c":["my name is Li Ming","my best friend","in my opinion","my own room","oh my god"],"b":"my 是 I 的形容词性物主代词，源自古英语 mīn，与 mine 同源。它必须放在名词前作定语，不能单独使用；若要单独用，要用名词性物主代词 mine，如 This book is mine。中国学习者常把 my 与 me 混用，说 me book，这是没有区分英语代词“格”和“性”的典型错误。"},
  "nanotechnology": {"u":"指纳米技术，常与 research、medicine 搭配。"},
  "narrative": {"u":"作名词指叙述；也指舆论中的「叙事」。"},
  "navigation": {"u":"指航行、导航技术；也指网站导航。"},
  "need": {"c":["need to do","in need of","need help","don't need to","if need be"],"b":"need 既可作实义动词也可作情态动词。作情态动词时多用于否定句和疑问句，如 You needn't worry。中国学习者常误加 to，如 needn't to go 是错的。need 作名词时常用 in need of，表示“需要”。"},
  "negative": {"u":"可指阴性、负数、底片，依语境而定"},
  "negligent": {"u":"指疏忽大意的，法律常用；名词为 negligence。"},
  "nervous": {"u":"be nervous about sth，介词用 about"},
  "never": {"c":["never mind","never again","never give up","never too late","have never been"],"b":"never 由古英语 ne（不）加 æfre（曾经）缩合而成，字面就是「任何时候都不」，因此它本身已含否定，不能再与 not 连用，写成 don't never 是双重否定错误。never mind 表示「没关系、别在意」，是日常高频口语。中国学习者还需注意 never 放句首时句子要部分倒装，如 Never have I seen such a thing。"},
  "nineteen": {"u":"与 ninety（九十）拼写易混，勿漏 -teen"},
  "no": {"c":["no problem at all","no longer available","have no idea","no way to know","there is no doubt"],"b":"no 源自古英语 nān（not one 的缩合），所以它天生带有「一个也没有」的意味，比 not any 语气更强。中国学习者常把 no 和 not 混用：no 直接修饰名词（no money），not 则需借助动词或 any（not have any money）。"},
  "not": {"c":["not at all","why not try again","not only but also","do not forget","not really my type"],"b":"not 是古英语 nāwiht（无物）的缩略，与 no 同源但功能不同：no 限定名词，not 否定动词、形容词或整个句子。常见误用是把 not 直接放在名词前，如不说 not money，而应说 no money 或 not any money。"},
  "now": {"c":["right now","now and then","from now on","by now","now that"],"b":"now 源自古英语 nū，与德语 nun 同源，本义就是「此刻」。它除了作时间副词，还可作连词，如 now that 表示「既然」。中国学习者常把 now 与 just now 混淆：just now 意为「刚才」，与一般过去时连用；而 now 通常与现在时连用。now that 引导原因状语从句，语气比 because 更强调条件已具备。"},
  "o'keeffe": {"u":"美国女画家，以花卉与沙漠题材著称。"},
  "obstruction": {"u":"多指具体堵塞物；法律用 obstruction of justice。"},
  "of": {"c":["a friend of mine","the city of Beijing","be proud of","a cup of tea","because of the rain"],"b":"of 源自古英语，本义就是“来自、属于”，是英语中最高频的介词之一。它常表示所属、数量、材料、来源等关系。中国学习者容易把“我的一个朋友”说成 a my friend，正确说法是 a friend of mine，这种“of + 名词性物主代词”的结构是汉语里没有的，需要专门记住。"},
  "off": {"c":["turn off the light","take off your coat","get off the bus","day off","off and on"],"b":"off 源自古英语 of，本义是「离开、脱离」，所以它既表示空间上的「离开」，如 get off the bus，也表示电器「关闭」，如 turn off。中国学习者要注意 off 与 from 的区别：off 强调脱离某表面，from 强调来源或起点。off and on（或 on and off）意为「断断续续地」，是常见的时间状语。"},
  "oh": {"c":["oh my god","oh no","oh well","oh really","oh dear"],"b":"oh 是英语中最古老的感叹词之一，源自古英语，模仿人惊讶、痛苦或醒悟时发出的自然声音，与汉语「哦」功能相似。它可表示惊讶、失望、领悟等多种情绪，具体含义靠语调区分。中国学习者常把 oh 与 ah 混用：oh 多表意外或醒悟，ah 多表恍然大悟或满意。书写时 oh 后通常接逗号。"},
  "okay": {"c":["okay with me","feel okay","okay then","that's okay","okay by me"],"b":"okay 源自 19 世纪美国的一个玩笑拼写 oll korrect，后缩写为 OK，逐渐成为全球通用词。它可作形容词、副词、感叹词。中国学习者常只用它表示「好」，其实 Are you okay? 还常用来询问对方是否安好。"},
  "on": {"c":["on the table","on Monday","on foot","on the internet","depend on you"],"b":"on 本义是“在……表面上”，与 in 的“在里面”相对。它还可表示具体某天、方式、关于、依靠等。中国学习者常混淆 on 与 in 的时间用法：on 用于具体某天或星期，如 on Sunday；in 用于月、年、季节。另外 on foot 表示“步行”，不能说 by foot，这是固定搭配。"},
  "one": {"c":["one by one","one another","one day","one of us","one more time"],"b":"one 源自古英语 ān，与德语 ein 同源，本义是「一」。它除了作数词，还可作代词，泛指「人们」，如 One should be honest。中国学习者常把 one 与 a 混用：one 强调数量「一个」，a 强调类别「某一个」。此外 one of 后接复数名词，但谓语动词用单数，如 one of the boys is，这是常见考点。"},
  "only": {"c":["only child","only a few","not only...but also","the only way","only too glad"],"b":"only 源自古英语 ānlic，由 ān（一）加 -lic（像……的）构成，本义是「独一无二的」，所以它天然带有「唯一」的意味。中国学习者易错点在于 not only 置于句首时需倒装：Not only did he come, but he also stayed。另外 only 的位置很敏感，位置不同意思会变，如 Only I told him 与 I told only him。"},
  "oppose": {"u":"oppose sth/doing sth；be opposed to 表示反对。"},
  "or": {"c":["or so","either ... or","or else","whether ... or not","more or less"],"b":"or 源自古英语 oþþe，表示选择。中国学习者常混淆 or 与 and 在否定句中的用法：否定句中通常用 or 而非 and，如 I don't like tea or coffee。or else 意为“否则”，语气较强，常用于警告。"},
  "our": {"c":["our own","in our opinion","our best","our daily life","our team"],"b":"our 是 we 的形容词性物主代词，来自古英语 ure。中国学习者常把 our 和 ours 混淆：our 后必须接名词，ours 独立使用，如 This is our book 与 This book is ours。此外 our 不能与 a 或 the 连用。"},
  "out": {"c":["go out","out of order","find out","out of date","work out"],"b":"out 源自古英语 ūt，本义是「向外」，与德语 aus 同源。它既可作副词也可作介词性小品词，与动词组合成大量短语动词，如 find out、work out、run out。中国学习者常混淆 out 与 outside：out 强调从内部到外部的动作，outside 强调位置在外。另外 out of 是一个固定组合，表示「从……出来」或「缺乏」。"},
  "over": {"c":["over there","all over the world","over and over","get over it","over the weekend"],"b":"over 源自古英语 ofer，本义是「在上方越过」，所以既有空间上的「在……上方」，也有「越过、超过」的引申义。中国学习者要注意它与 above 的区别：over 强调覆盖或跨越，above 只强调位置高于。over 还可表示「在……期间」，如 over the weekend，以及「结束」，如 The class is over。"},
  "overcome": {"c":["overcome difficulties","overcome the fear","overcome obstacles","be overcome with emotion","overcome a challenge"],"b":"overcome 是英语本土复合词，由 over（越过）加 come（来）构成，字面就是「越过、胜过」，古英语时期就已存在。它强调通过努力战胜困难，宾语多为 difficulty、fear、obstacle 等抽象障碍。注意 be overcome with/by 表示「被情绪压倒」，如 overcome with joy，与主动义区别明显。","u":"主动义为「克服困难」；be overcome with 表示「被情绪压倒」，注意"},
  "overdue": {"u":"指逾期未付或早该发生，常与 long 连用。"},
  "overestimate": {"u":"指估计过高；反义为 underestimate。"},
  "overlook": {"c":["overlook a mistake","overlook the fact that","overlook the importance of","a room overlooking the sea","overlook the possibility"],"b":"由 over（在上）+ look（看）构成，本义是「从高处往下看」，如房间俯瞰大海；引申为「看漏、忽视」，因为从上往下看反而容易漏掉细节。中国学习者常只记「忽视」一义，遇到 a room overlooking the garden 时不解其意，其实这正是它最原始的空间义。","u":"overlook 表「忽视」时是及物动词，直接跟宾语，不加 at。"},
  "overwhelm": {"c":["be overwhelmed by","overwhelm the senses","overwhelmed with work","overwhelming majority","feel overwhelmed"],"b":"古英语 whelm 意为「倾覆、淹没」，over- 加在其上，本义是「把……整个盖住、压垮」，像大水没顶。因此它既可指情绪上「不知所措」，也可指数量上「压倒性」。注意 overwhelming 作形容词常指「压倒性的」，如 overwhelming majority（绝大多数），并非「令人崩溃」。","u":"be overwhelmed by/with 表被压垮或不知所措；overwhe"},
  "paradigm": {"u":"paradigm shift 指根本性范式转换"},
  "paragraph": {"c":["the first paragraph","a short paragraph","in the last paragraph","write a paragraph about","paragraph by paragraph"],"b":"paragraph 源自希腊语 paragraphos，由 para-（旁边）加 graphein（写）构成，本义是古书页边用来标记段落起止的符号。它指围绕一个中心意思展开的文字块。中国学习者在写作中常忽略英语段落的「主题句」传统，即每段开头常有一句概括全段，这与汉语段落较松散的结构不同。","u":"指文章的自然段；首段说 the first paragraph。"},
  "participant": {"u":"a participant in sth，介词用 in"},
  "participate": {"c":["participate in","actively participate","participate in a debate","participate in class","refuse to participate"],"b":"participate 源自拉丁语 particeps（分享者），由 pars（部分）+ capere（拿取）构成，本义“取得一部分”，故指参与、分享。中国学习者最常见的错误是漏掉介词 in，直接说 participate the activity；必须说 participate in the activity。","u":"不及物动词，必须接 in，如 participate in an activit"},
  "passive": {"u":"指被动、消极；被动吸烟说 passive smoking。"},
  "pasture": {"u":"指牧场；习语 put out to pasture 意为使退休。"},
  "pathetic": {"c":["a pathetic sight","feel pathetic","a pathetic excuse","truly pathetic","a pathetic attempt"],"b":"源自希腊语 pathos（情感、痛苦），本义是「引发怜悯的」，与 sympathy（同情）、apathy（冷漠）同源。但现代口语中它常带贬义，指「差劲的、可悲的」，如 a pathetic excuse（蹩脚的借口）。中国学习者若只记「可怜的」，可能误用为褒义同情，实际语气常含轻蔑。","u":"本义可怜，口语常含贬义，指差劲、可悲。"},
  "pathology": {"u":"本义病理学；引申指病态、异常"},
  "people": {"c":["young people","a lot of people","people around the world","the Chinese people","people say that"],"b":"people 源自拉丁语 populus（民众），经古法语 pueple 进入英语。它作「人们」讲时本身就是复数，不能加 s，说 two peoples 是错的；但 peoples 可指「多个民族」，如 the peoples of Asia。中国学习者常把它与 person 混用：person 是可数单数，two persons 偏正式，日常更常说 two people。"},
  "perceive": {"c":["perceive a difference","perceive as a threat","perceive the world","perceive oneself as","be perceived to be"],"b":"源自拉丁语 percipere，per-（彻底）+ capere（抓取），本义是「抓住、领会」。它既指感官上的「察觉」，也指心智上的「理解、认为」，因此常与 as 连用表示「把……看作」。中国学习者常只记「察觉」一义，忽略 perceive A as B 这一高频结构，写作时容易漏掉 as。","u":"perceive A as B 表「把 A 看作 B」。"},
  "perennial": {"u":"植物学指多年生，引申为长期存在的"},
  "philanthropy": {"u":"指有组织的大额公益捐赠，比 charity 更正式。"},
  "philosopher": {"c":["a Greek philosopher","a political philosopher","philosopher of science","a philosopher king","a natural philosopher"],"b":"源自希腊语 philosophos，philos（爱）+ sophia（智慧），字面即「爱智慧的人」。古希腊人用这个词称呼探究万物本原的思想者，苏格拉底、柏拉图是代表。中国学习者易把它与 thinker 等同，其实 philosopher 更强调系统性的哲学研究，且 natural philosopher 在近代英语中曾指「自然科学家」。","u":"指哲学家，也可指有深刻见解的人。"},
  "philosophical": {"u":"引申为豁达的，be philosophical about"},
  "philosophy": {"c":["a philosophy of life","ancient Greek philosophy","the philosophy behind","study philosophy","personal philosophy"],"b":"philosophy 源自希腊语 philosophia，由 philos（爱）加 sophia（智慧）构成，本义是「对智慧的热爱」，所以哲学字面上就是「爱智之学」。中国学习者常把它只理解为学科「哲学」，其实 a philosophy of life（人生理念）也很常用，指个人对生活的根本看法，此时不必译成「哲学」。","u":"既指哲学学科，也指人生理念、宗旨。"},
  "phonetic": {"u":"phonetic alphabet 指音标字母表"},
  "picture": {"u":"in the picture 指了解情况；the bigger picture"},
  "please": {"c":["please come in","yes, please","please yourself","please be quiet","could you please"],"b":"please 源自拉丁语 placere（使高兴、取悦），经古法语 plaisir 进入英语，所以它既是礼貌用语「请」，也是动词「使高兴」，如 The result pleased us。中国学习者常忽略它在句中的位置：please 放句首后接动词原形，而 could you please 后也接动词原形。回答邀请时 yes, please 表示接受，no, thank you 表示婉拒。"},
  "plural": {"u":"语法指复数；引申指多元的"},
  "polish": {"u":"擦亮；润色文字。大写 Polish 指波兰的。"},
  "population": {"u":"指人口或种群；作主语谓语常用单数。"},
  "portable": {"u":"指轻便易携带的，常修饰设备、电脑等。"},
  "portfolio": {"c":["build a portfolio","investment portfolio","design portfolio","diversify one's portfolio","portfolio manager"],"b":"源自意大利语 portafoglio，由 portare（携带）+ foglio（纸张）构成，本指「随身携带的文件夹」，故有「作品集」义；后引申为银行、投资领域里「一组资产」，即投资组合。中国学习者易只记住「作品集」，忽略金融语境中「资产组合」这一高频用法。","u":"既指作品集，也指投资组合，注意金融语境含义。"},
  "possessive": {"u":"指占有欲强的；语法中指所有格的。"},
  "posture": {"u":"指身体姿势，也引申指态度、立场。"},
  "precaution": {"u":"指预防措施；常用 take precautions against。"},
  "precede": {"u":"易与 proceed（继续进行）混淆，注意区分"},
  "precious": {"u":"指珍贵的；口语中也可反讽，表「少得可怜」。"},
  "precise": {"c":["precise measurement","to be precise","precise definition","precise instructions","at that precise moment"],"b":"precise 源自拉丁语 praecidere（切断），本义“切得干净利落”，故引申为精确、确切。中国学习者易与 accurate 混：precise 强调细节精确、界定清楚，accurate 强调与事实相符。口语中 to be precise 意为“确切地说”。","u":"强调细节精确；常用 to be precise 表示“确切地说”。"},
  "prejudiceless": {"u":"指无偏见的；更常用 unbiased、impartial。"},
  "premise": {"u":"常用 on the premise that... 表示在……前提下。"},
  "prescribe": {"u":"指开处方，也指法规规定；勿与 describe 混。"},
  "preserve": {"c":["preserve the environment","preserve cultural heritage","preserve food","preserve one's health","well-preserved"],"b":"preserve 来自拉丁语 prae-（预先）+ servare（保护），本义是「事先保护起来」。它既指保护自然与文化遗产，也指用腌制、罐装等方法保存食物（preserved fruit 蜜饯）。中国学习者常把它与 reserve（预订、保留）混淆，两者拼写相近但含义不同。","u":"preserve 强调保护使其不受损，reserve 强调预留，注意区分。"},
  "principle": {"u":"勿与 principal 混；in principle 表原则上。"},
  "privileged": {"u":"feel privileged to do 表「感到荣幸」"},
  "production": {"u":"指生产、制作，也指戏剧影视作品。"},
  "progressive": {"u":"可指疾病进行性的、累进税的"},
  "protect": {"u":"protect...from/against 保护免受……。"},
  "protection": {"u":"不可数；protection against/from 防……。"},
  "psychology": {"c":["study psychology","child psychology","the psychology of consumers","a degree in psychology","reverse psychology"],"b":"由希腊语 psycho-（灵魂、心灵）加 -logy（学科）构成，字面即「研究心灵的学问」。同根词有 psychiatrist（精神科医生）、psychic（通灵的）。中文学习者常把 psychology 与 psychiatry 混淆：前者是心理学，后者是医学分支，专治精神疾病。","u":"指心理学；精神科医学是 psychiatry，勿混。"},
  "qin shi huang": {"u":"中国第一位皇帝，统一六国，陵墓有兵马俑。"},
  "quote": {"u":"可指引用，也可指报价、引语"},
  "radiation": {"u":"泛指辐射，如核辐射、放射治疗。"},
  "rapid": {"u":"较书面，多修饰 growth、change 等抽象过程。"},
  "reaffirm": {"u":"正式用词，指重申承诺、立场或决定。"},
  "really": {"c":["really good","really want to","not really","really like it","really? me too"],"b":"really 由 real 加副词后缀 -ly 构成，本义是“真实地”，后引申为程度副词“非常”。中国学习者常把它与 very 混淆：really 修饰动词或形容词，very 只修饰形容词或副词，如 I really like it 不能说 I very like it。"},
  "recipient": {"u":"指接受者、收件人，常与 of 连用。"},
  "reckless": {"u":"含贬义，指不顾后果；法律用语 reckless disregard。"},
  "recognition": {"u":"in recognition of 表为表彰；也指人脸识别。"},
  "redundant": {"u":"英式常指被裁员：be made redundant。"},
  "reflection": {"u":"指反射、映像，也指深思；on reflection 再一想。"},
  "reform": {"c":["carry out reforms","reform the system","sweeping reforms","educational reform","reform and opening up"],"b":"reform 由 re-（重新）+ form（形式）构成，字面即“重新塑形”。中国学习者常把它与 reformation 混淆：后者多指16世纪欧洲宗教改革，而泛指改革用 reform。另注意 reform 作名词时常用复数 reforms，如 economic reforms。","u":"作名词常用复数 reforms；作动词直接跟宾语，如 reform the sy"},
  "refund": {"u":"名词 get a refund；动词直接接宾语"},
  "regardless": {"c":["regardless of the cost","regardless of age","regardless of the outcome","continue regardless","regardless of what happens"],"b":"由 regard（注意、考虑）加 -less（不）构成，字面是「不加考虑的」。它最常用作介词短语 regardless of，意为「不管、不顾」。中国学习者常犯的错误是写成 regardless of 后接句子时漏掉引导词，如 regardless of it rains；正确应为 regardless of whether it rains 或 regardless of the rain。","u":"regardless of + 名词/wh-从句；单独 regardless 作"},
  "reliable": {"c":["a reliable source","reliable information","highly reliable","reliable evidence","a reliable witness"],"b":"由动词 rely（依赖）加后缀 -able（能够被……的）构成，字面即「可以被依赖的」。它与 reliant（依赖的）形近易混：reliable 形容「值得依靠的人或物」，reliant 则说「依赖于某物」，如 reliant on。中国学习者写作文时常用 reliable 修饰 data、source，这是地道搭配。","u":"指人或信息一贯可靠、靠得住。"},
  "religion": {"u":"可数名词；freedom of religion 宗教自由"},
  "reluctant": {"c":["be reluctant to do","reluctant agreement","a reluctant hero","seem reluctant","reluctant to admit"],"b":"源自拉丁语 reluctari（re-「反」+ luctari「挣扎」），本义是「挣扎反抗」，所以它比 unwilling 多一层「心里抵触、不太情愿」的意味。固定结构是 be reluctant to do sth，不能说 reluctant doing。名词形式 reluctance 也常考，如 with reluctance（勉强地）。","u":"固定用 be reluctant to do sth，不用 doing 形式。"},
  "reminder": {"u":"指提醒物或提示；a reminder of 使人想起……。"},
  "replica": {"u":"a replica of sth，指仿制复制品"},
  "reproduce": {"u":"指繁殖，也指复制、再现、重现。"},
  "republic": {"u":"源自 res publica；国名中常特指某共和国"},
  "resentment": {"u":"长期积怨，常搭 against/at/towards。"},
  "reserve": {"u":"可指预订，也指保留、储备、保护区"},
  "respectively": {"u":"用于按顺序一一对应，前面须有并列项"},
  "response": {"u":"in response to 表示「作为回应」，介词用 to"},
  "restore": {"c":["restore order","restore a building","restore confidence","restore to its former glory","restore power"],"b":"源自拉丁语 restaurare（重建、恢复），re-（重新）加词根表「建立」。它既可指修复实物（古建筑、文物），也可指恢复抽象事物（秩序、信心、供电）。中文学习者常误用 restore 表「归还」，其实表「归还」时更常用 return 或 give back。","u":"可指修复实物或恢复秩序、信心；表归还有限。"},
  "retirement": {"c":["take early retirement","retirement age","a retirement plan","retirement home","after retirement"],"b":"由动词 retire（退休）加 -ment 构成，词根是法语 retirer（撤回、退隐），本义是「退到安静处」。因此 retirement 既指「退休」这一行为，也指「退休生活」。中国学习者易与 resign（辞职）混淆：retirement 是因年龄或工龄正常退出职场，resign 是主动辞去职务，二者不可互换。","u":"指退休状态或时期；提前退休说 early retirement。"},
  "retrospective": {"u":"指回顾的；艺术展、医学研究中常用。"},
  "reveal": {"u":"字面「揭开面纱」，指揭示隐藏之事"},
  "revelation": {"u":"指被揭露的（常令人吃惊的）事实或启示。"},
  "revenue": {"c":["tax revenue","annual revenue","generate revenue","revenue from tourism","loss of revenue"],"b":"revenue 源自拉丁语 revenire（返回），本义“回来的东西”，即收回的钱，故指收入、税收。中国学习者易把它与 income 混：revenue 多指政府税收或企业营业收入，income 多指个人收入。注意 revenue 常作不可数名词。","u":"多指政府税收或企业收入，常不可数；annual revenue 指年收入。"},
  "revise": {"c":["revise the draft","revise for an exam","revise your essay","thoroughly revise the plan","revise the manuscript"],"b":"revise 来自拉丁语 revisere，本义是「再看一遍」，所以它同时有「修订」和「复习」两义，逻辑上都是「重新看」。英国学生说 revise for an exam 就是考前复习，而美国人多用 review。中国学习者常把它和 reverse（颠倒）混淆，注意词尾是 -vise 不是 -verse。","u":"英式英语中「复习迎考」用 revise for an exam，美式多用 rev"},
  "revive": {"c":["revive the economy","revive a tradition","revive from a coma","revive interest in","be revived after"],"b":"来自拉丁语 revivere（re-「再」+ vivere「活」），与 vivid、survive、vital 同根，本义「重新活过来」。既可指人苏醒、经济复苏，也可指潮流、传统「重新流行」。常见误用是把它当及物动词时忘了宾语，如 revive the economy 不能省略 the economy。","u":"可及物可不及物：revive the economy 或经济自身 revive。"},
  "rival": {"u":"指竞争同一目标的对手，中性词，非敌人。"},
  "said": {"c":["he said that","as I said before","said to me","it is said that","well said"],"b":"said 是 say 的过去式和过去分词，源自古英语 secgan。英语中 say 强调说话的内容，tell 强调告诉的对象，所以是 say something to somebody，不能说 say me。it is said that 是「据说」的固定句型，属于被动结构。中国学习者常把 said 与 told 混用，记住：said 后不直接接人，told 后必须接人。"},
  "scheme": {"u":"英式多指方案；美式多含贬义指阴谋。"},
  "scissors": {"u":"恒用复数；一把剪刀说 a pair of scissors。"},
  "scribble": {"u":"指潦草写或乱涂；scribble down 匆忙记下"},
  "script": {"u":"可指剧本，也指手迹、文字体系"},
  "scripture": {"u":"大写常指《圣经》；复数泛指宗教经典。"},
  "seduce": {"u":"指诱惑勾引；常用 seduce sb into doing。"},
  "senior": {"u":"比较用 be senior to，不用 than。"},
  "sensitive": {"c":["sensitive to criticism","highly sensitive skin","sensitive information","be sensitive to others' feelings","a sensitive issue"],"b":"sensitive 源自拉丁语 sentire（感觉），与 sense、sensation 同根，本义是「能感知的」。它有两层意思：一是感官或情绪上「易受刺激的」（sensitive skin），二是「体贴的、善解人意的」（sensitive to others）。中国学习者常把「体贴」误说成 considerate 而忽略 sensitive to 这一地道用法。","u":"表示「对…敏感/体贴」用 be sensitive to sth，介词固定为 t"},
  "separate": {"c":["separate the two groups","separate from each other","separate the whites from the yolks","keep them separate","separate into two parts"],"b":"源自拉丁语 separare，由 se-（分开）+ parare（准备、安排）构成，本义「分开放置」。作动词时重音在首音节，作形容词「分开的、单独的」时重音也在首音节，但拼写相同。中国学习者常忽略搭配：separate A from B（把 A 与 B 分开）是核心句型，不要写成 separate A and B。","u":"核心搭配 separate A from B，表示把两者分开。"},
  "separation": {"u":"separation from sb；legal separation"},
  "sequence": {"u":"指顺序或一连串；in sequence 依次。"},
  "seventeen": {"u":"与 seventy（七十）拼写易混，勿漏 -teen"},
  "she": {"c":["she said yes","she is my sister","she likes reading","she works hard","she and I"],"b":"she 源自古英语 hēo，是中古英语时期从复数代词中借形演变而来，与 he 同源但走了一条特殊路线。中国学习者常犯的错误是把 she 和 her 混用：she 只作主语，her 作宾语或定语。另外指代国家、船只、宠物时英语有时用 she 表亲切，这与汉语习惯不同，容易造成理解偏差。"},
  "shen": {"u":"作姓氏时首字母大写 Shen；勿与 Shenzhen 混淆。"},
  "shorten": {"u":"指缩短、变短；由 short 加 -en 构成。"},
  "should": {"c":["should do your best","you should know","should have done","why should I","should be careful"],"b":"should 源自古英语 sceolde，是 shall 的过去式，后来独立成为情态动词，表示「应该」。它可表达建议、义务或推测，如 He should be home by now（推测）。中国学习者易错点在于 should have done 表示「本该做而没做」，含责备或遗憾，与 must have done（对过去的肯定推测）意思完全不同，切勿混用。"},
  "silence": {"u":"指沉默、寂静；in silence 默默地。"},
  "silent": {"u":"remain silent 保持沉默；be silent about 对…缄口"},
  "silvicolous": {"u":"生态学术语，指林栖的，日常罕用"},
  "similar": {"u":"搭配 be similar to，不用 with。"},
  "sixteen": {"u":"重音在后；sweet sixteen 指女孩十六岁生日。"},
  "sleepness": {"u":"非标准词，宜改用 sleepless 或 unable to sleep。"},
  "so": {"c":["so far so good","so that we can","I think so","so much for today","not so fast"],"b":"so 源自古英语 swā（如此），兼有程度副词和因果连词两种功能。中国学习者易把 so 与 very 混用：so 后通常接形容词加 that 从句或 so...that 结构，而 very 不能直接引导结果从句。口语中 so 还常用来开启话题或表示「然后」。"},
  "some": {"c":["some of them","some day","some more","some other time","some kind of"],"b":"some 源自古英语 sum，表示“某个、一些”。中国学习者常混淆 some 与 any 的用法：肯定句用 some，否定句和疑问句通常用 any，但在表示请求或建议的疑问句中仍用 some，如 Would you like some tea?"},
  "something": {"c":["something else","something like","something to eat","or something","something of a"],"b":"something 由 some 和 thing 复合而成，古英语已有类似形式。中国学习者常犯的错误是在否定句中使用 something，标准英语否定句应用 anything，如 I don't have anything。但在表示请求的疑问句中仍可用 something。"},
  "spectacle": {"c":["a magnificent spectacle","make a spectacle of oneself","a spectacle of colour","watch the spectacle","a public spectacle"],"b":"spectacle 源自拉丁语 spectare（观看），与 spectator（观众）、spectacular（壮观的）同根，本义是「被看到的东西」。它指宏大场面或景象，也用于贬义 make a spectacle of oneself（当众出丑）。中国学习者容易只记「景象」，忽略这个固定短语，考试中常考。","u":"make a spectacle of oneself 意为「当众出丑」，是高频"},
  "spectator": {"u":"多指现场看比赛者；与 audience（听众/观众）辨析。"},
  "sponsor": {"u":"可指赞助者或提案人；动词义为赞助、发起。"},
  "spontaneous": {"u":"指未经安排、自然发生的，如自发掌声。"},
  "strengthen": {"c":["strengthen ties","strengthen the economy","strengthen one's resolve","strengthen muscles","strengthen cooperation"],"b":"strengthen 由 strength（力量）+ -en（使…）构成，-en 是古英语中常见的使役后缀，如 widen、deepen。它强调使某事物变得更强，常搭配 ties、economy、resolve 等抽象名词。中国学习者常把 strengthen 与 reinforce 混用，后者侧重「加固、增援」具体结构或论点。","u":"strengthen 后直接接宾语，如 strengthen ties/econ"},
  "study": {"u":"可指学习、研究、仔细察看，也指书房"},
  "stupidity": {"u":"指愚蠢或蠢事；语气重，批评他人慎用。"},
  "submit": {"c":["submit an application","submit to pressure","submit a report","submit evidence","submit oneself to"],"b":"submit 由 sub-（在下）+ mit（送）构成，字面“送到下面”，故既指“提交（下级呈交上级）”，也指“屈服于”。中国学习者易混淆两个义项：submit the report 是提交报告，submit to the enemy 才是向敌人屈服，介词 to 不可省。","u":"表“提交”直接跟宾语；表“屈服”须接 to，如 submit to pressu"},
  "subscribe": {"c":["subscribe to a magazine","subscribe to a channel","subscribe to the view","subscribe to a newsletter","cancel a subscription"],"b":"subscribe 来自拉丁语 subscribere，sub-（在下面）+ scribere（写），原指在文件下方签名表示同意，所以它既有「订阅」也有「赞同某观点」的意思。subscribe to a view 就是「认同某看法」，这一点常被中国学习者忽略，误以为它只能用于杂志或频道。","u":"表示「赞同某观点」用 subscribe to an idea/view，介词是"},
  "subsequent": {"c":["subsequent events","in subsequent years","subsequent to the meeting","a subsequent report","subsequent developments"],"b":"源自拉丁语 subsequi（跟随），由 sub-（在下、接着）+ sequi（跟随）构成，与 sequence、consequence 同源。它表示「随后的」，常与 to 连用，如 subsequent to his arrival（在他到达之后）。中国学习者在写作中易与 consequent 混用：subsequent 只表时间先后，consequent 强调因果导致的结果。","u":"表时间上随后；subsequent to 意为「在……之后」。"},
  "subsidiary": {"u":"名词指子公司；形容词指附属、次要的。"},
  "subtle": {"u":"指细微难察的，常修饰 difference、change 等。"},
  "summarize": {"u":"及物动词，归纳要点；to summarize 意为总之。"},
  "supervise": {"u":"指监督管理工作或人员，须带宾语。"},
  "supplement": {"u":"a supplement to sth，介词用 to"},
  "surge": {"u":"a surge in sth 表激增，介词用 in"},
  "surgeon": {"u":"指外科医生，与内科医生 physician 相对。"},
  "suspicion": {"u":"指对某人的猜疑；under suspicion 受怀疑。"},
  "symbolic": {"u":"表「象征某物」用 be symbolic of，勿漏 of。"},
  "sympathy": {"c":["express sympathy for","feel sympathy for","have sympathy with","out of sympathy","deep sympathy"],"b":"sympathy 由希腊语 syn-（共同）+ pathos（感受）构成，字面就是「共同感受」，与 empathy（共情）、apathy（冷漠）同族。它既可指对他人不幸的同情，也可指对某主张的赞同（in sympathy with）。中国学习者常把 sympathy 与 empathy 混用，后者强调设身处地。","u":"「对某人表示同情」用 express/feel sympathy for sb。"},
  "symphony": {"u":"指交响乐；symphony orchestra 指交响乐团。"},
  "synchronize": {"u":"指使时间一致；口语常简略为 sync。"},
  "tacent": {"u":"极书面冷僻词，日常用 silent 更自然。"},
  "tempo": {"u":"本指乐曲速度，引申为生活节奏。"},
  "temporal": {"u":"既指时间的，也指世俗的，与 spiritual 相对。"},
  "temporarily": {"c":["temporarily closed","temporarily suspended","temporarily unavailable","temporarily out of service","temporarily housed"],"b":"temporarily 来自拉丁语 tempus（时间），与 temporary（暂时的）、contemporary（同时代的）同根，本义是「与时间有关的」。它表示某状态只持续一段时间，常与 closed、suspended、unavailable 等搭配。中国学习者常把它与 temporarily 和 permanently 搞混，后者是「永久地」，二者常成对出现。","u":"temporarily 意为「暂时地」，常与 closed、suspended "},
  "temporary": {"c":["temporary job","temporary measure","temporary solution","for temporary use","temporary setback"],"b":"temporary 源自拉丁语 tempus（时间），本义“只持续一段时间的”。中国学习者易与 temporal（时间的、世俗的）混淆。temporary 强调短暂、非永久，反义词是 permanent；常见搭配 temporary job/measure 表示临时工作或权宜之计。","u":"常与 permanent 对比；修饰名词表“临时的”，如 a temporary"},
  "tendency": {"c":["a tendency to do","have a tendency towards","a growing tendency","show a tendency","counter a tendency"],"b":"来自拉丁语 tendere（伸展、朝向），与 tend（倾向）同源，本义是「朝某方向伸展」。因此 tendency 指事物自然发展的趋向，常接 to do 或 towards。中国学习者易犯的错误是写成 tendency of doing；正确结构是 a tendency to do sth 或 a tendency towards sth，注意介词搭配。","u":"常用 have a tendency to do sth 表倾向。"},
  "tendon": {"u":"跟腱固定说 Achilles tendon，不用 heel tendon。"},
  "tense": {"u":"指紧张的或拉紧的；语法中另指时态。"},
  "tension": {"c":["ease tension","rising tension","political tension","muscle tension","tension between A and B"],"b":"tension 源自拉丁语 tendere（拉紧），本义“拉紧的状态”，故既指物理张力，也指心理或局势紧张。中国学习者易与 stress 混：tension 多指关系、局势的紧张，stress 多指个人压力。常用 ease tension 表示缓和紧张局势。","u":"指紧张局势或张力；常用 ease/reduce tension 表示缓和紧张。"},
  "terrace": {"u":"指露台、梯田；排屋说 terraced house。"},
  "terrain": {"u":"指地形地势；rough terrain 崎岖地形。"},
  "terrestrial": {"u":"指陆地的或地球的；与水生、天体相对。"},
  "territory": {"c":["national territory","disputed territory","enter the territory","uncharted territory","territory of a country"],"b":"territory 源自拉丁语 terra（土地），本义“土地、领地”。除地理上的领土外，它还常引申为“领域、范围”，如 unfamiliar territory 指陌生领域。中国学习者易把 territory 与 land 混用：territory 强调主权管辖范围，land 更泛指土地。","u":"指领土或领域；常用 on/into the territory of... 表示"},
  "testify": {"u":"作证反对某人用 testify against sb。"},
  "thank": {"c":["thank you very much","thank you for your help","thanks a lot","thank God","no, thank you"],"b":"thank 源自古英语 þancian，本义是「想到、感念」，与 thought（思想）同源，所以「感谢」最初是「记着别人的好」。中国学习者常把 thank 与 appreciate 弄混：thank 后接人，appreciate 后接事，如 I thank you 与 I appreciate your help。另外 thanks 是名词复数，口语中 thanks a lot 比 thank you 更随意。"},
  "that": {"c":["that is why","that one over there","I know that he is right","at that time","that's a good idea"],"b":"that 与 this 相对，指较远的人或事物，也可作关系代词和连词。它源自古英语指示词，与 the、there、then 同源，都含“指出来”的意思。中国学习者常把 that 从句前的 that 与关系代词 that 混淆，其实前者只起连接作用、不作句子成分，后者要在从句中充当主语或宾语。"},
  "the": {"c":["the same as","the other day","all the time","the more the better","on the whole"],"b":"the 源自古英语指示词 sē，本义相当于「那个」，后来弱化为定冠词，用来指双方已知或上文提到的人或物。中国学习者常漏用 the，尤其在特指前文已出现的事物、独一无二事物（the sun）以及最高级前，这是受汉语无冠词系统影响所致。"},
  "theater": {"u":"英式拼 theatre，美式拼 theater。"},
  "them": {"c":["tell them the truth","give them a call","one of them","both of them","let them know"],"b":"them 源自古英语 him，后受北欧语影响变为 them，是 they 的宾格。常见误用是把 them 与 they 混用：作主语用 they，作宾语用 them，如 They are here 与 I saw them，中国学习者有时会漏掉宾语形式。"},
  "then": {"c":["and then","by then","since then","then and there","now and then"],"b":"then 来自古英语 þanne，本义是指示时间。中国学习者常把 then 和 than 搞混：then 表时间，than 表比较。另外 by then 意为“到那时”，常与过去完成时连用，如 By then he had left，不能说成 By then he has left。"},
  "there": {"c":["there is no need","over there","there you go","there and back","there is no doubt"],"b":"there 源自古英语 þǣr，本义是「在那个地方」，后虚化为存在句的引导词 there is/are。中国学习者常把 there is 与 have 混用：汉语「有」在英语中若表存在用 there is，若表拥有用 have。另外 there 作引导词时，真正的主语在 be 之后。"},
  "thesis": {"u":"复数为 theses；论文与论点两义都常用。"},
  "they": {"c":["they say that","they are all here","they don't know","as they say","they themselves"],"b":"they 源自古诺斯语 þeir，是英语中唯一从北欧借来的第三人称代词。它可指代复数人或物，现代英语中还常用作单数性别中立代词，指代未知性别的人。中国学习者易把 they 与 them 混用：they 作主语，them 作宾语。"},
  "thirteen": {"u":"重音在后；文化上常与不吉相联。"},
  "this": {"c":["this is my book","this morning","this way please","this one here","what is this"],"b":"this 是指示代词，指较近的人或事物，与 that 相对。它源自古英语 þis，与 the、there 同源，都有“指出来”的意味。this 还能修饰时间，如 this week、this year，表示当前这个周期。中国学习者常把 this 和 it 混用：介绍某人时用 This is my friend，而不是 It is my friend。"},
  "title": {"u":"既是标题也是头衔，体育中指冠军称号。"},
  "to": {"c":["look forward to","from A to B","to my surprise","come to an end","agree to a plan"],"b":"to 源自古英语介词 tō，本义为「朝向」，由空间方向引申出时间终点、对象、目的等多种用法。它既是介词又是不定式标记，学习者易混淆：look forward to 中的 to 是介词，后接动名词，而 want to 中的 to 接动词原形，须按搭配区分。"},
  "too": {"c":["too much","too many","me too","too late","too good to be true"],"b":"too 源自古英语 tō，本义是“过分地”，后引申出“也”的意思。中国学习者常混淆 too 与 also：too 多用于句末，also 多用于句中，如 I like it too 与 I also like it。too much 修饰不可数名词，too many 修饰可数名词。"},
  "topical": {"u":"指当前热门的；医学上指局部的、外用的。"},
  "transaction": {"c":["complete a transaction","a business transaction","cash transaction","transaction costs","process a transaction"],"b":"源自拉丁语 transigere（完成、了结），trans-（穿过）加 agere（做、驱动），本义是「把事情办完」，故兼有「交易」和「办理」义。银行、电商场景常用。中文学习者易忽略它也可指「事务的办理过程」，不限于买卖交易。","u":"既指交易，也指事务的办理过程。"},
  "transfer": {"c":["transfer money","transfer to another school","bank transfer","transfer of power","transfer the file"],"b":"transfer 由 trans-（跨越）+ fer（携带）构成，字面即“从一处带到另一处”，故可指转账、转学、调动、转让等。中国学习者常误用双宾语，如 transfer me the money；正确说法是 transfer money to me，用 to 引出接受者。","u":"常用 transfer sth to sb；名词搭配 bank transfer"},
  "transform": {"c":["transform into something new","transform the economy","completely transform society","transform data into information","transform one's life"],"b":"源自拉丁语 transformare，由 trans-（跨越、改变）加 forma（形状）构成，本义是「改变形状」。中文学习者常误把它当 change 的随意替换，其实 transform 强调彻底、根本性的改变，程度远强于 change，且常与 into 连用表示变成某物。","u":"强调彻底改变，常与 into 连用，程度强于 change。"},
  "transient": {"u":"指短暂易逝的；比 temporary 更强调自然消逝。"},
  "transition": {"c":["transition to a new job","a smooth transition","in transition","the transition from school to work","make the transition"],"b":"transition 来自拉丁语 transire（越过、通过），trans-（跨越）+ ire（走），本义是「从一处走到另一处」。它强调过程而非结果，所以常说 a smooth transition、in transition。中国学习者常误把它当动词用，其实动词是 transition（美式可作动词）但更稳妥的表达是 make the transition to。","u":"名词常用 the transition from A to B，表示「从A到B的"},
  "transmit": {"u":"transmit sth to sb；信号、数据、疾病均可用。"},
  "transport": {"c":["public transport","transport goods","means of transport","air transport","transport system"],"b":"transport 由 trans-（跨越）+ port（携带）构成，与 transfer 同源，本义“搬运”。英式英语中作名词常指交通工具系统，如 public transport；美式则多用 transportation。中国学习者易把 transport 与 traffic 混：traffic 指交通流量，transport 指运输方式或工具。","u":"英式多用 public transport；美式常说 transportatio"},
  "two": {"c":["two of them","in two weeks","two hundred people","two and a half hours","between the two"],"b":"two 来自古英语 twā，与德语 zwei、拉丁语 duo 同源，属印欧语系最古老的数词之一。它有个独特的语法点：与复数名词连用时后面不再加 -s，如 two hundred 而非 two hundreds。另外「两人一组」常用 in twos，这个复数形式表示「成双成对」，是学习者容易忽略的用法。"},
  "ultimate": {"u":"指最终的、根本的；强调终点或极限。"},
  "unconscious": {"u":"既指昏迷，也指无意识、未察觉。"},
  "undermine": {"u":"指暗中逐渐削弱信心、权威等抽象事物。"},
  "undertake": {"c":["undertake a task","undertake research","undertake to do something","undertake a project","undertake a journey"],"b":"由 under（在……之下）加 take（拿、承担）构成，字面即「把事情揽到手下」，故义为「承担、着手做」。注意 undertake to do sth 表示「承诺做某事」，是较正式的用法。中文学习者常只记「从事」，忽略其「承诺」义。","u":"undertake to do sth 意为承诺做某事，较正式。"},
  "undo": {"c":["undo the damage","undo a button","undo your mistake","undo the knot","undo the changes"],"b":"古英语原为 undon，由 un-（相反）+ do（做）构成，字面即「反着做」，所以既指「解开」（undo a button 解开纽扣），也指「撤销、消除」（undo the damage 弥补损害）。计算机时代 undo 成为编辑软件的核心功能「撤销」。中国学习者易只记「解开」，忽略「消除影响、撤销操作」的抽象义。","u":"既可指解开纽扣等，也可指撤销操作、消除影响。"},
  "unprecedented": {"u":"由 un- + precedent + -ed 构成，指史无前例的。"},
  "up": {"c":["get up","up and down","give up","up to you","look up"],"b":"up 源自古英语 up，本义是「向上」，与德语 auf 同源。它与动词结合构成大量短语动词，如 get up、give up、look up，其中不少已脱离「向上」的字面义，转为抽象含义。中国学习者常把 up to 误解为「向上到」，其实它表示「由……决定」或「多达」。up 还可作形容词表示「醒着的」。"},
  "us": {"c":["let us go","give us a hand","between us","join us","tell us about it"],"b":"us 源自古英语 us，是 we 的宾格形式。常见误用是在主语位置误用 us，如 Us are students 应为 We are students；另外 let's 是 let us 的缩写，但 let's 包括听话者，let us 有时不包括，语义略有差别。"},
  "utilization": {"u":"正式用语，指资源或产能的利用，如利用率。"},
  "vacation": {"u":"美式英语常用；on vacation 表示在度假。"},
  "vasco da gama": {"u":"葡萄牙航海家，1498年开辟到印度的海路。"},
  "vector": {"u":"指矢量；也指疾病媒介或传播载体。"},
  "vegetarian": {"u":"指不吃肉者，多仍吃蛋奶；纯素为 vegan。"},
  "verdict": {"u":"指陪审团裁决，也指定论；reach a verdict。"},
  "very": {"c":["very good","very much","the very best","very well","not very happy"],"b":"very 源自拉丁语 verus（真实的），经古法语 verai 进入英语，本义是「真正地」，后来弱化为程度副词「很」。中国学习者最常见的误用是用 very 直接修饰动词，说成 I very like it，正确说法是 I like it very much。另外 very 不能修饰比较级，要表达「好得多」得用 much better 而非 very better。"},
  "vital": {"c":["play a vital role","vital to success","of vital importance","vital organs","a vital decision"],"b":"源自拉丁语 vita（生命），本义是「与生命有关的」，所以既有「充满活力的」义，也引申出「生死攸关、至关重要」义。注意 vital 作「至关重要」时通常不用于人，说某人重要宜用 important；而 vital organs 指心、脑等维持生命的器官。","u":"表至关重要时多修饰事物，不直接形容人。"},
  "vitamin": {"u":"指维生素；常见 vitamin C、vitamin deficiency。"},
  "vivid": {"c":["a vivid memory","vivid colours","a vivid imagination","vivid description","vividly remember"],"b":"源自拉丁语 vividus（有生气的），与 vivere（生活）同源，本义是「充满生命力的」。因此它既形容颜色「鲜艳」，也形容记忆、描写「生动逼真」。中国学习者常把 vivid 只用于颜色，其实 a vivid memory（清晰的记忆）、a vivid imagination（丰富的想象力）同样地道。","u":"既形容颜色鲜艳，也形容记忆、描写生动。"},
  "vulnerable": {"u":"常用 be vulnerable to sth 表易受伤害。"},
  "want": {"c":["want to go","want a drink","want you to know","want for nothing","all I want"],"b":"want 源自古诺斯语 vanta，本义是「缺少」，后引申为「想要」。它与汉语「想要」不完全对应：want 后接不定式，不能接动名词，如不能说 want going。中国学习者常犯的错误是 want sb to do sth 结构中漏掉 to。另外 want 表「需要」时可用主动表被动，如 The car wants washing。"},
  "warehouse": {"u":"指大型仓储设施，非零售商店。"},
  "was": {"c":["was born in","was about to leave","was there a moment","he was late again","it was raining hard"],"b":"was 是 be 的过去式单数形式，源自古英语 wesan（存在、停留）。中国学习者常把 was 与 were 混用，记住口诀：I/he/she/it 用 was，you/we/they 用 were。另外 was 在口语中常弱读，但书面语中不可省略。"},
  "way": {"c":["in this way","on the way home","find a way out","by the way","no way"],"b":"way 来自古英语 weg，本义是「道路」，后来从具体的路引申出抽象的「方法、方式」。汉语说「用……方法」常直译成 use this way，但英语更地道的是 in this way 或 this way。by the way 字面是「顺路」，所以引申为「顺便说一句」；on the way 强调在途中。注意 way 表示方法时后面常接 to do 或 of doing。"},
  "we": {"c":["we are students","we all agree","here we go","we need to talk","we should help each other"],"b":"we 是第一人称复数主格代词，源自古英语 wē，与德语 wir 同源。它通常包括说话者本人，有时也能泛指“人们”，如 We should protect the environment。中国学习者要注意 we 是主格，作宾语要用 us，作定语要用 our，三者不能混用，这是英语代词有格变化的典型体现。"},
  "were": {"c":["were you there","we were friends","if I were you","were born in","as it were"],"b":"were 源自古英语 wæron，是 be 的过去式复数，也用于虚拟语气。最典型的虚拟用法是 If I were you，即使主语是 I 也用 were，这是英语残留的虚拟式，中国学习者常误写成 If I was you。"},
  "what": {"c":["what is this","what time is it","what about you","what a nice day","I don't know what to do"],"b":"what 源自古英语 hwæt，属于 wh- 疑问词家族，与 who、when、where 同源，核心含义是“未知的事物”。它既可作疑问代词，也可引导名词性从句。中国学习者常把 what 和 which 混用：what 范围不限定，which 则在一定范围内选择，如 What color do you like? 与 Which color, red or blue?"},
  "when": {"c":["when I was young","when it comes to","since when","when in Rome","when possible"],"b":"when 源自古英语 hwænne，兼作疑问副词和连词。常见误用是在时间状语从句中画蛇添足加 will，如 When I will arrive, I will call you，其实从句要用一般现在时表将来，应为 When I arrive。"},
  "where": {"c":["where are you from","where do you live","where it hurts","where possible","the place where"],"b":"where 源自古英语 hwær，兼具疑问和关系副词功能。常见误用是在定语从句中重复使用：The city where I live in 中的 in 是多余的，因为 where 已相当于 in which，应说 The city where I live。"},
  "who": {"c":["who is that","who are you","who did it","who else","who knows"],"b":"who 源自古英语 hwa，属疑问代词家族。常见误用有两处：一是把 who 与 whom 混用，作介词宾语时应说 to whom；二是在定语从句中，先行词指人时才用 who，指物要用 which，中文学习者常一律用 who。"},
  "why": {"c":["why not","why so serious","why bother","the reason why","why on earth"],"b":"why 源自古英语 hwy，由疑问词根 hwa 加工具格后缀构成，本义近似「凭什么」。why not 后接动词原形表示建议，如 Why not go?，中国学习者常误加 to，说成 Why not to go，这是高频错误。"},
  "will": {"c":["will do","will be","will you please","I will try","will not give up"],"b":"will 源自古英语 willan，本义是「意愿」，后来语法化为将来时助动词，同时保留「愿意、决心」的实义。中国学习者常把 will 与 be going to 混用：will 表临时决定或预测，be going to 表事先计划或有迹象的预测。另外 will 作名词时意为「意志、遗嘱」，如 strong will，不要与助动词混淆。"},
  "witchcraft": {"u":"多用于历史或奇幻语境，指施巫术行为。"},
  "with": {"c":["with my friends","with a smile","deal with problems","agree with you","with regard to"],"b":"with 源自古英语 wið（相对、对抗），原义是「背对背」，后演变为「在一起」。中国学习者易把 with 与 and 混用：with 表伴随但不作主语，With Tom and I went 是错的，应说 Tom and I went together 或 I went with Tom。"},
  "withdraw": {"u":"过去式 withdrew；取款、退出、撤回均用。"},
  "would": {"c":["would like to","would rather","would you mind","would love to","as luck would have it"],"b":"would 源自古英语 wolde，是 will 的过去式，但现代英语中更多用于虚拟、礼貌和习惯。would like 比 want 更客气。常见误用是 would rather 后接动词原形，却误加 to，如 would rather to stay 应为 would rather stay。"},
  "yeah": {"c":["yeah right","yeah sure","oh yeah","yeah I know","yeah yeah"],"b":"yeah 是 yes 的口语弱化形式，源于十九世纪末美国英语，模拟轻松随意的应答语气。它比 yes 更随意，多用于朋友间对话，正式场合应避免。中国学习者常把 yeah 与 yep、yup 混用，后两者更随意甚至略显粗俗。yeah right 常带反讽意味，表示「才怪」，并非真的同意，这是易误解的用法。"},
  "yes": {"c":["yes please","yes of course","say yes to","yes and no","oh yes"],"b":"yes 源自古英语 gese，由「如此」之意演变而来。文化差异值得注意：英语中回答否定疑问句时，yes 仍表示肯定事实，如 Aren't you tired? 若确实累应说 Yes, I am，中国学习者常按中文习惯答 No，造成误解。"},
  "you": {"c":["you and me","thank you very much","you never know","see you later","if you like"],"b":"you 源自古英语 ēow，本是第二人称复数与宾格形式，后来逐渐取代单数 thou 成为通用的人称代词。中国学习者常犯的错是把 you 只当「你」，忽略它在口语中可泛指「任何人」，如 You never know until you try，此处并非特指对方。"},
  "your": {"c":["your name is Tom","your best friend","in your opinion","your own choice","what's your problem"],"b":"your 是 you 的形容词性物主代词，源自古英语 ēower。它必须放在名词前作定语，不能单独使用；单独使用要用 yours，如 This book is yours。中国学习者常把 your 与 you're 混淆，前者是“你的”，后者是 you are 的缩写，写作时两者混用是常见错误，需要特别注意。"},
  "zheng he": {"u":"明朝航海家，率船队七下西洋远达东非。"},
}

/**
 * 查一个单词的用法补充（固定搭配 / 背景 / 补缺用法）。
 * @param {string} form 单词词形（大小写不敏感）
 * @returns {{ collocations: string[], background: string, usage: string } | null}
 */
export function usageExtraOf(form) {
  if (typeof form !== 'string') return null
  const entry = usageExtra[form.toLowerCase()]
  if (!entry || typeof entry !== 'object') return null
  return {
    collocations: Array.isArray(entry.c) ? entry.c.filter((s) => typeof s === 'string') : [],
    background: typeof entry.b === 'string' ? entry.b : '',
    usage: typeof entry.u === 'string' ? entry.u : '',
  }
}

export default usageExtra
